/* 西电811 电路题库：课后题 + 考研真题 + 期末真题 */
window.PRO_BANK_EC={"chapters":[{"id":"ec-basic","area":"电路","name":"电路基本概念和定律","short":"基本定律","weight":12,"rule":"mixed"},{"id":"ec-analyze","area":"电路","name":"电阻电路分析","short":"电阻电路","weight":14,"rule":"mixed"},{"id":"ec-dynamic","area":"电路","name":"动态电路（一阶时域分析）","short":"动态电路","weight":14,"rule":"mixed"},{"id":"ec-sinusoidal","area":"电路","name":"正弦稳态电路","short":"正弦稳态","weight":14,"rule":"mixed"},{"id":"ec-resonance","area":"电路","name":"频率响应与谐振电路","short":"谐振","weight":10,"rule":"mixed"},{"id":"ec-twoport","area":"电路","name":"二端口电路","short":"二端口","weight":11,"rule":"mixed"}],"questions":[{"id":"p01","ch":"ec-basic","qt":"填空","pts":5,"t":"课后题","src":"邱关源《电路》","q":"电阻 R₁=4Ω 与 R₂=6Ω 串联后接在 20V 电压源上，求 R₁ 两端电压。","a":"8V","s":"串联分压：U₁ = 20 × 4/(4+6) = 8V。"},{"id":"p02","ch":"ec-basic","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"求图示 a、b 两端的等效电阻：12Ω 与 6Ω 并联，再与 4Ω 串联。","a":"8Ω","s":"并联部分：12×6/(12+6) = 4Ω；串联 4Ω 后总电阻 4+4 = 8Ω。"},{"id":"p03","ch":"ec-basic","qt":"选择","pts":5,"t":"课后题","src":"邱关源《电路》","q":"关于理想电压源与理想电流源的内阻，下列说法正确的是：","o":["A. 理想电压源内阻为 0，理想电流源内阻为 0","B. 理想电压源内阻为 0，理想电流源内阻为 ∞","C. 理想电压源内阻为 ∞，理想电流源内阻为 0","D. 两者内阻均为 ∞"],"a":"B","s":"理想电压源恒压故内阻为 0；理想电流源恒流故内阻为 ∞。"},{"id":"p04","ch":"ec-basic","qt":"填空","pts":5,"t":"课后题","src":"邱关源《电路》","q":"5Ω 电阻上流过 2A 电流，求电阻消耗的功率。","a":"20W","s":"P = I²R = 2² × 5 = 20W。"},{"id":"p05","ch":"ec-basic","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"单回路电路：10V 电压源、2Ω 电阻与 3Ω 电阻串联，求回路电流 I。","a":"I = 2A","s":"由 KVL：10 = 2I + 3I，I = 10/5 = 2A。"},{"id":"p06","ch":"ec-analyze","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"用节点电压法求节点电压：12V 电压源串 2Ω 接到节点 a；节点 a 经 4Ω 接地；节点 a 经 2Ω 串 6V 电压源接地。求 Ua。","a":"7.2V","s":"节点方程：(1/2+1/4+1/2)Ua = 12/2 + 6/2 = 9，即 1.25Ua = 9，Ua = 7.2V。"},{"id":"p07","ch":"ec-analyze","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"求含源单口网络的戴维南等效电路：10V 电压源与 2Ω 电阻串联后引出端口。","a":"开路电压 10V，等效电阻 2Ω","s":"端口开路电压即电压源电压 10V；独立源置零后从端口看入的电阻为 2Ω。"},{"id":"p08","ch":"ec-analyze","qt":"选择","pts":5,"t":"课后题","src":"邱关源《电路》","q":"叠加定理适用于：","o":["A. 任意电路","B. 线性电路","C. 非线性电路","D. 仅直流电路"],"a":"B","s":"叠加定理只适用于线性电路（线性电阻、独立源与受控源）。"},{"id":"p09","ch":"ec-analyze","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"某线性含源网络戴维南等效为 Voc=12V、Req=3Ω。负载 RL 取何值时获得最大功率？最大功率为多少？","a":"RL = 3Ω，Pmax = 12W","s":"最大功率传输条件 RL = Req = 3Ω；Pmax = Voc²/(4Req) = 144/12 = 12W。"},{"id":"p10","ch":"ec-dynamic","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"RC 串联电路：R=2kΩ，C=1μF，u_C(0₊)=0，t=0 时接入 10V 直流电压。求 u_C(t)。","a":"u_C(t) = 10(1 − e^(−500t)) V","s":"三要素法：u_C(0₊)=0，稳态 u_C(∞)=10V，τ=RC=2×10⁻³ s，u_C(t)=10(1−e^(−t/τ))。"},{"id":"p11","ch":"ec-dynamic","qt":"填空","pts":5,"t":"课后题","src":"邱关源《电路》","q":"RL 串联电路的时间常数 τ = ?","a":"τ = L/R","s":"RL 电路时间常数 τ = L/R（R 为电感两端等效电阻）。"},{"id":"p12","ch":"ec-dynamic","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"换路前电路已稳定，电感电流 i_L(0₋)=2A。开关动作后瞬间求 i_L(0₊)。","a":"i_L(0₊) = 2A","s":"换路定则：电感电流不能跃变，i_L(0₊) = i_L(0₋) = 2A。"},{"id":"p13","ch":"ec-dynamic","qt":"选择","pts":5,"t":"课后题","src":"邱关源《电路》","q":"一阶电路三要素法中的三个要素是：","o":["A. 初始值、稳态值、时间常数","B. 电压、电流、电阻","C. 幅值、频率、相位","D. 零输入、零状态、全响应"],"a":"A","s":"三要素：初始值 f(0₊)、稳态值 f(∞)、时间常数 τ。"},{"id":"p14","ch":"ec-sinusoidal","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"正弦电压 u(t) = 10√2·cos(ωt + 30°) V，写出其相量形式。","a":"U̇ = 10∠30° V","s":"相量的模取有效值 10，辐角取初相 30°。"},{"id":"p15","ch":"ec-sinusoidal","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"电阻 R=3Ω 与感抗 X_L=4Ω 串联，求等效复阻抗 Z 及其模。","a":"Z = 3 + j4 Ω，|Z| = 5Ω","s":"串联阻抗直接相加：Z = 3 + j4，|Z| = √(3²+4²) = 5。"},{"id":"p16","ch":"ec-sinusoidal","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"二端网络 U̇ = 100∠0° V，İ = 2∠−60° A，求有功功率 P。","a":"P = 100W","s":"P = UIcosφ = 100 × 2 × cos60° = 100W。"},{"id":"p17","ch":"ec-sinusoidal","qt":"填空","pts":5,"t":"课后题","src":"邱关源《电路》","q":"功率因数 λ 与阻抗角 φ 的关系是？","a":"λ = cosφ","s":"功率因数 λ = cosφ = P/(UI)。"},{"id":"p18","ch":"ec-resonance","qt":"填空","pts":5,"t":"课后题","src":"邱关源《电路》","q":"RLC 串联电路的谐振频率 f₀ = ?","a":"f₀ = 1/(2π√(LC))","s":"串联谐振条件 ω₀ = 1/√(LC)，故 f₀ = 1/(2π√(LC))。"},{"id":"p19","ch":"ec-resonance","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"RLC 串联电路 L=0.1H，C=10μF，求谐振角频率 ω₀。","a":"ω₀ = 1000 rad/s","s":"ω₀ = 1/√(LC) = 1/√(0.1×10×10⁻⁶) = 1/√(10⁻⁶) = 1000 rad/s。"},{"id":"p20","ch":"ec-resonance","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"串联谐振电路中 R=10Ω，ω₀=1000 rad/s，L=0.1H，求品质因数 Q 和通频带 B。","a":"Q = 10，B = 100 rad/s","s":"Q = ω₀L/R = 1000×0.1/10 = 10；B = ω₀/Q = 100 rad/s。"},{"id":"p21","ch":"ec-twoport","qt":"解答","pts":10,"t":"课后题","src":"邱关源《电路》","q":"T 形二端口网络：串臂 Z₁=2Ω、Z₂=4Ω，并臂 Z₃=4Ω。求 Z 参数矩阵。","a":"Z₁₁=6Ω，Z₂₂=8Ω，Z₁₂=Z₂₁=4Ω","s":"Z₁₁ = Z₁+Z₃ = 6；Z₂₂ = Z₂+Z₃ = 8；Z₁₂ = Z₂₁ = Z₃ = 4（互易网络）。"},{"id":"p22","ch":"ec-twoport","qt":"填空","pts":5,"t":"课后题","src":"邱关源《电路》","q":"理想变压器变比 n=2，次级接 8Ω 负载，求折算到初级的等效电阻。","a":"32Ω","s":"理想变压器阻抗变换：R′ = n²R = 4 × 8 = 32Ω。"},{"id":"p23","ch":"ec-twoport","qt":"选择","pts":5,"t":"课后题","src":"邱关源《电路》","q":"二端口网络四套参数（Z、Y、H、A）中，最常用于级联分析的是：","o":["A. Z 参数","B. Y 参数","C. H 参数","D. A 参数（传输参数）"],"a":"D","s":"A 参数（传输参数）矩阵相乘即可级联，适合多级网络分析。"},{"id":"pb16","ch":"ec-basic","qt":"解答","pts":10,"t":"课后题","src":"王松林《电路基础》课后题","q":"12 V 电压源串联 3 Ω 电阻后再串 6 Ω 电阻，求 6 Ω 电阻上的电压和电流。","a":"电压 8 V，电流 4/3 A。","s":"串联分压：U = 12×6/(3+6) = 8 V；电流 I = 12/(3+6) = 4/3 A（KVL、欧姆定律）。"},{"id":"pb17","ch":"ec-analyze","qt":"解答","pts":10,"t":"课后题","src":"王松林《电路基础》课后题","q":"12 V 电压源与 4 Ω 电阻串联，再接 12 Ω 与 6 Ω 并联的负载（端口 a-b 为并联网络两端）。求 a-b 端口的戴维南等效电路。","a":"开路电压 Uoc = 6 V，等效电阻 Req = 2 Ω。","s":"并联等效电阻 12∥6 = 4 Ω；Uoc = 12×4/(4+4) = 6 V；将电压源置零（短路），Req = 4∥4 = 2 Ω。"},{"id":"pb18","ch":"ec-dynamic","qt":"解答","pts":10,"t":"课后题","src":"王松林《电路基础》课后题","q":"一阶 RC 电路：R=5 kΩ，C=100 μF，电容初始电压 uC(0+)=2 V，换路后稳态电压 uC(∞)=10 V。用三要素法求 uC(t)，t≥0。","a":"uC(t) = 10 - 8e^(-2t) V（t≥0）。","s":"时间常数 τ=RC=5×10³×100×10⁻⁶=0.5 s。三要素公式：uC(t)=uC(∞)+[uC(0+)-uC(∞)]e^(-t/τ)=10+(2-10)e^(-2t)=10-8e^(-2t) V。"},{"id":"pb19","ch":"ec-sinusoidal","qt":"解答","pts":10,"t":"课后题","src":"王松林《电路基础》课后题","q":"R=3 Ω 与感抗 XL=4 Ω 串联，接在电压有效值 U=10 V 的正弦电源上。求电流有效值 I、功率因数 cosφ 和有功功率 P。","a":"I = 2 A，cosφ = 0.6，P = 12 W。","s":"阻抗模 |Z|=√(3²+4²)=5 Ω，I=U/|Z|=2 A；cosφ=R/|Z|=3/5=0.6；P=I²R=4×3=12 W。"},{"id":"pb20","ch":"ec-resonance","qt":"解答","pts":10,"t":"课后题","src":"王松林《电路基础》课后题","q":"RLC 串联谐振电路：R=2 Ω，L=1 H，C=0.25 F。求谐振角频率 ω0、谐振频率 f0、品质因数 Q 和通频带 B。","a":"ω0 = 2 rad/s，f0 = 1/π ≈ 0.318 Hz，Q = 1，B = 2 rad/s。","s":"ω0=1/√(LC)=1/√0.25=2 rad/s；f0=ω0/(2π)=1/π Hz；Q=ω0L/R=2/2=1；通频带 B=ω0/Q=2 rad/s。"},{"id":"pb21","ch":"ec-twoport","qt":"解答","pts":10,"t":"课后题","src":"王松林《电路基础》课后题","q":"二端口 T 型网络：端口 1-1′ 串联 3 Ω 电阻，再接 4 Ω 电阻跨接于输出端口 2-2′（4 Ω 上端为节点，下端为公共端）。求 Z 参数矩阵。","a":"Z11 = 7 Ω，Z12 = Z21 = 4 Ω，Z22 = 4 Ω。","s":"Z11=3+4=7 Ω（端口 2 开路时端口 1 输入电阻）；Z22=4 Ω（端口 1 开路时端口 2 输入电阻）；转移阻抗 Z12=Z21=4 Ω（互易网络）。"},{"id":"r19-13","seq":13,"part":"电路","qt":"填空","pts":5,"ch":"ec-basic","q":"1. 电路如图 1 所示，求 1A 的电流源产生的功率为多少。[图1：含 $7\\ \\mathrm V$、$3\\ \\mathrm V$ 电压源，$1.5\\ \\mathrm A$、$1\\ \\mathrm A$ 电流源及 $1\\Omega$、$2\\Omega$、$3\\Omega$、$4\\Omega$、$0.5\\Omega$ 电阻的电路（拓扑见图）]","img":"pro-img/2019_p05.jpg","a":"$1\\ \\mathrm{W}$","s":"由电路求得 1A 电流源两端电压为 $1\\ \\mathrm{V}$，故其产生的功率 $P=1\\times1=1\\ \\mathrm{W}$。（电路图 OCR 损毁，以答案页结果为准。）","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r19-14","seq":14,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"2. 电路如图 2 所示，参考节点如图所示，求节点电压为多少。[图2：含电流源（$1.5\\ \\mathrm A$、$3.5\\ \\mathrm A$、$1\\ \\mathrm A$）与电阻的二节点电路（见图）]","img":"pro-img/2019_p05.jpg","a":"$2\\ \\mathrm{V}$","s":"列节点方程：$(\\tfrac12+\\tfrac13+1)u_1-u_2=1.5-3.5$，$-u_1+(1+\\tfrac12)u_2=1+1.5$；整理得 $-3u_1+7.5u_2=6$、$10.5u_2=21$，故 $u_2=2\\ \\mathrm{V}$。","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r19-15","seq":15,"part":"电路","qt":"填空","pts":5,"ch":"ec-dynamic","q":"3. 电路如图所示，电容 $C=2\\ \\mathrm F$，已知其电压 $u_C(t)=3(1-e^{-t})\\ \\mathrm V$，电流 $i$ 取非关联参考方向，求电流 $i(t)$（$t\\geq0$）。[图：电容 $C=2\\,\\mathrm F$ 支路，$i$ 与 $u_C$ 非关联参考方向（见图）]","img":"pro-img/2019_p05.jpg","a":"$i(t)=-6e^{-t}\\ \\mathrm{A}$（$t\\geq0$）","s":"$i(t)=-C\\dfrac{\\mathrm du_C}{\\mathrm dt}=-2\\times3e^{-t}=-6e^{-t}\\ \\mathrm{A}$（$t\\geq0$）。","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r19-16","seq":16,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"4. 电路如图 3 所示，其中网络 N 的伏安关系如右图所示，求电流 $i$ 为多少。[图3：网络 N 与 $10\\ \\mathrm V$ 电压源、$2\\ \\Omega$ 电阻串联的电路；右图为 N 的伏安特性（$U_{oc}=-6\\ \\mathrm V$、$R_{eq}=2\\ \\Omega$）]","img":"pro-img/2019_p05.jpg","a":"$4\\ \\mathrm{A}$","s":"由网络 N 的伏安关系得 N 的 $U_{oc}=-6\\ \\mathrm V$、$R_{eq}=2\\ \\Omega$。由 KVL：$(2+2)i+(-6)-10=0$，解得 $i=4\\ \\mathrm{A}$。","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r19-17","seq":17,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"5. 电路如图 4 所示，已知 $i(t)=100\\sqrt2\\cos(10^4t+30^\\circ)\\ \\mathrm{mA}$、电路吸收功率 $P=10\\ \\mathrm W$，功率因数为 $\\lambda=\\dfrac{\\sqrt2}{2}$，求电压 $u(t)$。[图4：正弦稳态电路，$i$、$u$ 关联参考方向（见图）]","img":"pro-img/2019_p05.jpg","a":"$u(t)=200\\cos(10^4t+75^\\circ)\\ \\mathrm V$","s":"$\\lambda=\\cos\\varphi=\\dfrac{\\sqrt2}{2}$ 且 $\\varphi>0$，故 $\\varphi=45^\\circ$；由 $P=UI\\cos\\varphi$ 得 $U=\\dfrac{P}{I\\cos\\varphi}=\\dfrac{10}{0.1\\times\\frac{\\sqrt2}{2}}=100\\sqrt2\\ \\mathrm V$（有效值），幅值 $200\\ \\mathrm V$。故 $u(t)=200\\cos(10^4t+30^\\circ+45^\\circ)=200\\cos(10^4t+75^\\circ)\\ \\mathrm V$。","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r19-18","seq":18,"part":"电路","qt":"填空","pts":5,"ch":"ec-dynamic","q":"6. 电路如图 5 所示，$t=0$ 时开关 S 闭合，闭合前电路已经处于稳态，求 $t\\geq0$ 时电流 $i_L$ 的零输入响应。[图5：含 $12\\ \\mathrm V$ 电压源、$2\\ \\Omega$、$8\\ \\Omega$ 电阻与电感 $L=3.2\\ \\mathrm{mH}$ 的电路，开关 S 于 $t=0$ 闭合（见图）]","img":"pro-img/2019_p06.jpg","a":"$i_L(t)=3.5e^{-500t}\\ \\mathrm{A}$（$t\\geq0$）","s":"$t=0_-$ 时 $i_L(0_-)=1.5+2=3.5\\ \\mathrm A$，故 $i_L(0_+)=3.5\\ \\mathrm A$；零输入状态下 $i_L(\\infty)=0$；$\\tau=\\dfrac{L}{R_{eq}}=\\dfrac{3.2\\times10^{-3}}{2\\parallel8}=2\\times10^{-3}\\ \\mathrm s$，故 $i_L(t)=3.5e^{-500t}\\ \\mathrm A$。","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r19-19","seq":19,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"7. 电路如图 6 所示，电流源 $I_s=2\\angle0^\\circ\\ \\mathrm A$，当 $Z_L$ 为多大时，其上可获得最大的功率值。[图6：电流源 $I_s=2\\angle0^\\circ$A 与 $j6\\ \\Omega$、$6\\ \\Omega$、$1\\ \\Omega$ 及负载 $Z_L$ 的电路（见图）]","img":"pro-img/2019_p06.jpg","a":"$Z_L=4-3j\\ \\Omega$","s":"将 $Z_L$ 断开，从两端看进去的等效阻抗 $Z_{eq}=(j6\\parallel6)+1=3+3j+1=4+3j\\ \\Omega$；由最大功率传输定理，当 $Z_L=Z_{eq}^*=4-3j\\ \\Omega$ 时获得最大功率。","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r19-20","seq":20,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"8. 电路如图 7 所示，$N$ 为无源线性网络，已知当 $U_s=8\\ \\mathrm V$，$R=3\\ \\Omega$ 时，$I=0.5\\ \\mathrm A$；当 $U_s=18\\ \\mathrm V$，$R=4\\ \\Omega$ 时，$I=1\\ \\mathrm A$。求当 $U_s=30\\ \\mathrm V$，$R=10\\ \\Omega$ 时，$I=?$ [图7：含源 $U_s$、无源线性网络 $N$ 与电阻 $R$ 的电路（见图）]","img":"pro-img/2019_p06.jpg","a":"$I=1\\ \\mathrm A$","s":"对除 $R$ 之外的部分做戴维南等效，设 $U_{oc}=kU_s$、$R_{eq}=R_0$。由 $0.5=\\dfrac{8k}{R_0+3}$、$1=\\dfrac{18k}{R_0+4}$ 解得 $k=0.5$、$R_0=5\\ \\Omega$。故 $U_s=30\\ \\mathrm V$、$R=10\\ \\Omega$ 时 $I=\\dfrac{0.5\\times30}{5+10}=1\\ \\mathrm A$。","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r19-21","seq":21,"part":"电路","qt":"填空","pts":5,"ch":"ec-twoport","q":"9. 电路如图 8 所示，写出该电路的 Z 参数方程。[图8：含电阻 $R_1$、$R_2$ 与耦合电感 $L_1$、$L_2$（互感 $M$）的二端口电路（见图）]","img":"pro-img/2019_p06.jpg","a":"$\\mathbf{Z}=\\begin{bmatrix}R_1+j\\omega L_1 & j\\omega M\\\\ j\\omega M & R_2+j\\omega L_2\\end{bmatrix}$","s":"$U_1=i_1(R_1+j\\omega L_1)+i_2(j\\omega M)$，$U_2=i_1(j\\omega M)+i_2(R_2+j\\omega L_2)$，故 $\\mathbf{Z}=\\begin{bmatrix}R_1+j\\omega L_1 & j\\omega M\\\\ j\\omega M & R_2+j\\omega L_2\\end{bmatrix}$。","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r19-22","seq":22,"part":"电路","qt":"解答","pts":7,"ch":"ec-dynamic","q":"1.（7分）图 9 所示电路，已知 $u_C(0_-)=0\\ \\mathrm V$，$t<0$ 时开关 S 打开；当 $t=0$ 时开关 S 闭合；当 $t=2\\ \\mathrm s$ 时开关 S 又打开。求 $t\\geq0$ 时的 $u_C$ 响应。[图9：含 $8\\ \\mathrm V$ 电压源、$6\\ \\Omega$、$2\\ \\Omega$ 电阻与电容 $C=2\\ \\mathrm F$ 的一阶电路（见图）]","img":"pro-img/2019_p06.jpg","a":"$u_C(t)=\\begin{cases}6-6e^{-t/3}\\ \\mathrm V,&0\\leq t<2\\\\6\\left(1-e^{-2/3}\\right)e^{-(t-2)/12}\\ \\mathrm V,&t\\geq2\\end{cases}$","s":"$0\\leq t<2$：$u_C(0_+)=u_C(0_-)=0$，$u_C(\\infty)=\\dfrac{6}{6+2}\\times8=6\\ \\mathrm V$，$\\tau_1=(2\\parallel6)\\times2=3\\ \\mathrm s$，故 $u_C(t)=6-6e^{-t/3}$。$t\\geq2$：$u_C(2_-)=6-6e^{-2/3}$，$u_C(\\infty)=0$，$\\tau_2=6\\times2=12\\ \\mathrm s$，故 $u_C(t)=6\\left(1-e^{-2/3}\\right)e^{-(t-2)/12}$。","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r19-23","seq":23,"part":"电路","qt":"解答","pts":7,"ch":"ec-resonance","q":"2.（7分）图 10 所示电路，电源 $u_s(t)=10\\cos(\\omega t)\\ \\mathrm V$。若电源角频率 $\\omega$ 可变，$\\omega$ 等于多少时，电流表的读数最大，并求出该最大值，此时电路的品质因数是多少。[图10：含耦合电感（互感 $M=20\\ \\mu\\mathrm H$）、$1\\ \\Omega$ 电阻与 $100\\ \\mathrm{pF}$ 电容的串联谐振电路（见图）]","img":"pro-img/2019_p07.jpg","a":"$\\omega_0=10^7\\ \\mathrm{rad/s}$；电流表最大读数 $I=5\\sqrt2\\ \\mathrm A$；品质因数 $Q=1000$。","s":"去耦等效后发生串联谐振时电流表读数最大，$\\omega_0=\\dfrac{1}{\\sqrt{LC}}=\\dfrac{1}{\\sqrt{100\\times10^{-6}\\times100\\times10^{-12}}}=10^7\\ \\mathrm{rad/s}$；此时 $I=\\dfrac{U_s}{R}=\\dfrac{10/\\sqrt2}{1}=5\\sqrt2\\ \\mathrm A$；$Q=\\dfrac{\\omega_0L}{R}=\\dfrac{10^7\\times100\\times10^{-6}}{1}=1000$。","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r19-24","seq":24,"part":"电路","qt":"解答","pts":8,"ch":"ec-resonance","q":"3.（8分）如图 11 所示并联谐振电路，已知 $L=200\\ \\mu\\mathrm H$、$C=0.2\\ \\mathrm{nF}$、$R=100\\ \\mathrm{k}\\Omega$。(1) 求电路的品质因数 $Q$；(2) 求谐振电阻的阻值。[图11：并联谐振电路（见图）]","img":"pro-img/2019_p07.jpg","a":"(1) $\\omega_0=5\\times10^6\\ \\mathrm{rad/s}$，$Q=100$；(2) $5\\times10^4\\ \\Omega$。","s":"$\\omega_0=\\dfrac{1}{\\sqrt{LC}}=\\dfrac{1}{\\sqrt{200\\times10^{-6}\\times0.2\\times10^{-9}}}=5\\times10^6\\ \\mathrm{rad/s}$，$Q=\\omega_0RC=5\\times10^6\\times100\\times10^3\\times0.2\\times10^{-9}=100$；谐振电阻为 $5\\times10^4\\ \\Omega$。（第(2)问题干 OCR 损毁，以答案页结果为准。）","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r19-25","seq":25,"part":"电路","qt":"解答","pts":8,"ch":"ec-analyze","q":"4.（8分）$N$ 为线性含源网络，根据图 12-a 及图 12-b 中给出的电压电流数据，确定图 12-c 中的电压 $U$ 的值为多少。[图12-a：N 与 $1\\ \\Omega$ 电阻及 $2\\ \\mathrm A$ 电流源；图12-b：N 与 $5\\ \\mathrm V$ 电压源及 $1\\ \\mathrm A$ 电流源；图12-c：N 与 $1\\ \\Omega$、$3\\ \\Omega$ 电阻、$1\\ \\mathrm A$ 电流源及 $5\\ \\mathrm V$ 电压源，求 $U$（具体拓扑见图）]","img":"pro-img/2019_p07.jpg","a":"$U=2.75\\ \\mathrm V$","s":"设 N 的戴维南等效为 $U_{oc}$、$R_{eq}$。由图12-a：$U_{oc}=2(1+R_{eq})$；由图12-b：$U_{oc}=5+R_{eq}$。解得 $U_{oc}=8\\ \\mathrm V$、$R_{eq}=3\\ \\Omega$。对图12-c 用叠加定理：仅 $1\\ \\mathrm A$ 电流源作用 $U'=1\\times(3\\parallel1)=0.75\\ \\mathrm V$；仅 $U_{oc}$ 作用 $U''=\\dfrac{8}{1+3}\\times1=2\\ \\mathrm V$。故 $U=U'+U''=2.75\\ \\mathrm V$。","t":"真题","y":2019,"src":"西电8112019真题"},{"id":"r20-13","seq":13,"part":"电路","qt":"填空","pts":5,"ch":"ec-basic","q":"电路如图1所示，求电流 $I$ 的值是____。[图1：含 10V 电压源、3A 电流源及 5Ω、15Ω、2Ω 电阻，求电流 I，见图]","img":"pro-img/2020_p04.jpg","a":"$2.5$ A","s":"由 KVL（或等效变换）得 $10+40=(15+5)I$，解得 $I=2.5$ A。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r20-14","seq":14,"part":"电路","qt":"填空","pts":5,"ch":"ec-basic","q":"电路如图2所示，求 10V 电压源发出的功率是____。[图2：含 10V、6V 电压源，1A、3A 电流源及 8Ω、5Ω、3Ω 电阻，见图]","img":"pro-img/2020_p04.jpg","a":"$22.5$ W（发出）","s":"由 KCL $I+1+3=0.5+1.25$，解得流经 10V 电压源的电流 $I=-2.25$ A；吸收功率 $P=10I=-2.25\\times10=-22.5$ W，即发出功率 $22.5$ W。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r20-15","seq":15,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"电路如图3所示，已知 $u_s(t)=9e^{-t}$ V，$i_s(t)=6\\cos 2t$ A，求 $i(t)=$____。[图3：含 $u_s(t)$、$i_s(t)$、$L=0.1$ H 及 2Ω、4Ω、3Ω 电阻，见图]","img":"pro-img/2020_p04.jpg","a":"$e^{-t}-2\\cos 2t$ A","s":"由叠加定理：$u_s$ 单独作用时 $i_1=\\dfrac{9e^{-t}}{6+3}=e^{-t}$ A；$i_s$ 单独作用时 $i_2=-\\dfrac{3}{3+6}\\cdot 6\\cos 2t=-2\\cos 2t$ A；故 $i(t)=e^{-t}-2\\cos 2t$ A。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r20-16","seq":16,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"电路如图4所示，已知 $\\omega=10^3$ rad/s，电流 $I=4\\angle 0^\\circ$ A，电压 $U=80+j200$ V，求电容 $C$ 的值是____。[图4：RLC 串联电路，含 R=20Ω、L=0.1H、C，见图]","img":"pro-img/2020_p05.jpg","a":"$20\\,\\mu$F","s":"$Z=\\dfrac{U}{I}=\\dfrac{80+j200}{4\\angle 0^\\circ}=20+j50\\ \\Omega$；又 $Z=R+j\\omega L-\\dfrac{j}{\\omega C}=20+j(10^3\\times0.1-\\dfrac{1}{10^3C})=20+j50\\ \\Omega$，故 $100-\\dfrac{1}{10^3C}=50$，解得 $C=20\\ \\mu$F。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r20-17","seq":17,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"电路如图5所示，已知 $R=10^4\\ \\Omega$，电压源 $U_s=100\\angle 0^\\circ$ V，则 $n$ 等于____时负载 $R_L$ 的功率达到最大。[图5：含理想变压器 1:n、j8Ω、4Ω 及负载 $R_L=1\\ \\Omega$，见图]","img":"pro-img/2020_p05.jpg","a":"$n=0.01$","s":"负载反射到初级的电阻为 $R_L/n^2=1/n^2$，最大功率传输要求其等于源内阻 $R=10^4\\ \\Omega$，故 $1/n^2=10^4$，$n=0.01$。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r20-18","seq":18,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"电路如图6所示，已知 $U_s=4\\angle 0^\\circ$ V，则该电路的性质是____（容性，感性）。[图6：含 j4Ω、j8Ω、-j4Ω、4Ω 阻抗，见图]","img":"pro-img/2020_p05.jpg","a":"容性","s":"$Z=j4+4+\\dfrac{j8(-j4)}{j8-j4}=4+j4+\\dfrac{32}{j4}=4+j4-j8=4-j4\\ \\Omega$，虚部 $X=-4<0$，故为容性。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r20-19","seq":19,"part":"电路","qt":"填空","pts":5,"ch":"ec-resonance","q":"电路如图7所示，若以 $u_c$ 为输出，则该电路是____（低通，高通，带通）电路。[图7：RC 电路，见图]","img":"pro-img/2020_p05.jpg","a":"低通","s":"$H(j\\omega)=\\dfrac{\\frac{1}{j\\omega C}}{R+\\frac{1}{j\\omega C}}=\\dfrac{1}{1+j\\omega RC}$；$\\omega\\to 0$ 时 $|H|=1$，$\\omega\\to\\infty$ 时 $|H|=0$，故为低通。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r20-20","seq":20,"part":"电路","qt":"填空","pts":5,"ch":"ec-resonance","q":"电路如图8所示，为一电容抽头的并联谐振电路，已知谐振频率为 62.8 MHz，$C_1=400$ pF，$C_2=100$ pF，求电路中的电感 $L=$____。[图8：电容抽头并联谐振电路，见图]","img":"pro-img/2020_p06.jpg","a":"$8\\times10^{-8}$ H","s":"等效电容 $C=\\dfrac{C_1C_2}{C_1+C_2}=\\dfrac{400\\times100}{400+100}=80$ pF；$L=\\dfrac{1}{(2\\pi f_0)^2C}=\\dfrac{1}{(6.28\\times6.28\\times10^7)^2\\times80\\times10^{-12}}=8\\times10^{-8}$ H。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r20-21","seq":21,"part":"电路","qt":"填空","pts":5,"ch":"ec-twoport","q":"电路如图9所示的二端口网络，则该网络的 Z 参数矩阵为____。[图9：含 R、L、C 的 T 型二端口网络，见图]","img":"pro-img/2020_p06.jpg","a":"$Z=\\begin{bmatrix}R+j\\omega L & R\\\\ R & R+\\frac{1}{j\\omega C}\\end{bmatrix}$","s":"$U_1=j\\omega L\\,I_1+R(I_1+I_2)=(R+j\\omega L)I_1+R\\,I_2$；$U_2=R(I_1+I_2)+\\dfrac{1}{j\\omega C}I_2=R\\,I_1+(R+\\dfrac{1}{j\\omega C})I_2$；故 $Z=\\begin{bmatrix}R+j\\omega L & R\\\\ R & R+\\frac{1}{j\\omega C}\\end{bmatrix}$。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r20-22","seq":22,"part":"电路","qt":"解答","pts":8,"ch":"ec-analyze","q":"（8分）电路如图10所示，试用节点法求图中受控源的电压 $U_k$。[图10：含 10V、12V、6V 独立源，0.5Ω、1Ω、2Ω 电阻及受控源 3U，见图]","img":"pro-img/2020_p06.jpg","a":"$U_k=-36$ V","s":"节点方程 $(1+2)U_0-2U_k=12$，且 $U_1-U_2=10$、$U_k=U_2+6U$，联立解得 $U_k=-36$ V。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r20-23","seq":23,"part":"电路","qt":"解答","pts":9,"ch":"ec-dynamic","q":"（9分）电路如图11所示，$t<0$ 时，开关 S1 处于闭合状态，开关 S2 处于断开状态，电路已经处于稳定状态；当 $t=0$ 时，断开开关 S1；$t=0.1$ s 时，闭合开关 S2，求 $t\\ge 0$ 时 $u_c(t)$ 和 $i(t)$。（注：$e=2.72$）[图11：含 1mA 电流源、10kΩ、10kΩ、10μF 电容及开关 S1、S2，见图]","img":"pro-img/2020_p06.jpg","a":"$u_c(t)=\\begin{cases}10(1-e^{-10t})\\ \\text{V}, & 0\\le t<0.1\\ \\text{s}\\\\ 5+1.32e^{-20(t-0.1)}\\ \\text{V}, & t\\ge 0.1\\ \\text{s}\\end{cases}$；$i(t)=\\begin{cases}e^{-10t}\\ \\text{mA}, & 0\\le t<0.1\\ \\text{s}\\\\ -0.264e^{-20(t-0.1)}\\ \\text{mA}, & t\\ge 0.1\\ \\text{s}\\end{cases}$","s":"（1）$0\\le t<0.1$ s：$u_c(0_+)=u_c(0_-)=0$，稳态 $u_c(\\infty)=10\\times10^3\\times1\\times10^{-3}=10$ V，$\\tau_1=RC=10\\times10^3\\times10\\times10^{-6}=0.1$ s，故 $u_c(t)=10(1-e^{-10t})$ V，$i(t)=C\\dfrac{du_c}{dt}=10\\times10^{-6}\\times100e^{-10t}=e^{-10t}$ mA。（2）$t\\ge 0.1$ s：$u_c(0.1_+)=u_c(0.1_-)=10(1-e^{-1})=6.32$ V，稳态 $u_c(\\infty)=(10k\\parallel10k)\\times10^{-3}=5$ V，$\\tau_2=(10k\\parallel10k)\\times10\\times10^{-6}=0.05$ s，故 $u_c(t)=5+(6.32-5)e^{-20(t-0.1)}=5+1.32e^{-20(t-0.1)}$ V；$i(t)=C\\dfrac{du_c}{dt}=10\\times10^{-6}\\times1.32\\times(-20)e^{-20(t-0.1)}=-0.264e^{-20(t-0.1)}$ mA。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r20-24","seq":24,"part":"电路","qt":"解答","pts":5,"ch":"ec-resonance","q":"（5分）电路如图12所示，已知 $L=10$ mH，输入电压的频率可变，当 $\\omega=10^3$ rad/s 时 $i(t)$ 的值最大，当 $\\omega=10^4$ rad/s 时 $i(t)$ 的值为 0，求电路中两个电容的值。[图12：含 L、C₁、C₂ 及 R 的谐振电路，见图]","img":"pro-img/2020_p07.jpg","a":"$C_1=1\\ \\mu$F，$C_2=99\\ \\mu$F","s":"当 $\\omega=10^4$ rad/s 时 $i=0$，$L$ 与 $C_1$ 发生并联谐振，$C_1=\\dfrac{1}{\\omega^2L}=\\dfrac{1}{(10^4)^2\\times10\\times10^{-3}}=1\\ \\mu$F；当 $\\omega=10^3$ rad/s 时 $i$ 最大，发生串联谐振，此时总阻抗虚部为 0，解得 $C_2=99\\ \\mu$F。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r20-25","seq":25,"part":"电路","qt":"解答","pts":8,"ch":"ec-analyze","q":"（8分）电路如图13所示，已知 $N$ 为不含独立源的线性电阻网络，已知输出电压 $u=0.5u_s$；若在输出端接上 5Ω 的电阻，则输出电压 $u=0.1u_s$。问在输出端接上 20Ω 的电阻时，输出电压 $u$ 与激励 $u_s$ 的关系是什么？[图13：线性无源电阻网络 N，见图]","img":"pro-img/2020_p07.jpg","a":"$u=0.25u_s$","s":"对 $N$ 作戴维南等效，开路电压 $u_{oc}=ku_s$，由开路时 $u=0.5u_s$ 得 $k=0.5$；接 5Ω 时 $\\dfrac{5}{5+R_o}\\times0.5u_s=0.1u_s$，解得 $R_o=20\\ \\Omega$；接 20Ω 时 $u=\\dfrac{20}{20+R_o}\\times0.5u_s=\\dfrac{20}{40}\\times0.5u_s=0.25u_s$。","t":"真题","y":2020,"src":"西电8112020真题"},{"id":"r21-14","seq":14,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"1. 如图1所示电路 [图1：含二端电路 N 与电阻的电路]，二端电路 N 两端电压为 $9\\,V$，则 ab 两节点间电压 $u_{ab}$ 为____。","img":"pro-img/2021_p06.jpg","a":"$u_{ab}=-3\\,V$（原文符号 OCR 存疑，值 $3\\,V$）","s":"解析：将电路 N 用 $9\\,V$ 电压源替换，列节点电压方程解得 $u_{ab}=-3\\,V$（解析 OCR 残缺）。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r21-15","seq":15,"part":"电路","qt":"填空","pts":5,"ch":"ec-basic","q":"2. 电路如图2所示 [图2：含受控电流源 $3i$ 的电路]，受控电流源提供的功率为____。","img":"pro-img/2021_p06.jpg","a":"$15\\,W$","s":"解析：由 KVL、KCL，$20i+5=10i$，$i=-0.5\\,A$，$u=20i=-10\\,V$，$p=3i\\cdot u=3\\times(-0.5)\\times(-10)=15\\,W$。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r21-16","seq":16,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"3. 图3(a)所示的电路 [图3(a)：含二端电路 N 的电路]，二端电路 N 的 VCR 特性如图3(b)所示 [图3(b)：N 的 VCR 特性]，当 ab 间开路时，$u_o=-6.5\\,V$，则 ab 端的电压 $u_{ab}$ 为____。","img":"pro-img/2021_p06.jpg","a":"$10\\,V$","s":"解析：$u=2i+u_o$，且 $u_o=-6.5\\,V$，由戴维南等效解得 $u_{ab}=10\\,V$。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r21-17","seq":17,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"4. 正弦稳态电路如图4所示 [图4：正弦稳态电路，含 $\\cos t$ 源、$2F$ 电容、$1H$ 电感]，负载 $Z_L$ 为既有电阻又有动态元件的负载，$Z_L=$ ____ 时可以获得最大功率。","img":"pro-img/2021_p06.jpg","a":"$Z_L=2+j1\\,\\Omega$（共轭匹配 $Z_L=Z_{th}^*$，原文 OCR 存疑）","s":"解析：$\\omega=1\\,rad/s$，求戴维南等效阻抗 $Z_{th}$，$Z_L=Z_{th}^*$ 时获得最大功率（解析 OCR 残缺，$Z_{th}$ 值见图4）。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r21-18","seq":18,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"5. 图5所示电路 [图5：含 $14\\,V$ 源与受控源的电路]，电压 $U=$ ____。","img":"pro-img/2021_p07.jpg","a":"$2\\,V$","s":"解析：$14=3\\times U+4U$，即 $14=7U$，$U=2\\,V$。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r21-19","seq":19,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"6. 电路如图6所示 [图6：含 $10\\,V$ 源、$5\\,\\Omega$、$9\\,\\Omega$ 与受控电流源 $0.9i$ 的电路]，电压 $U_{ab}=$ ____。","img":"pro-img/2021_p07.jpg","a":"$2\\,V$","s":"解析：$10=5\\times0.9i$，$i=\\tfrac{20}{9}\\,A$，$U_{ab}=9\\times(i-0.9i)=9\\times0.1i=2\\,V$。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r21-20","seq":20,"part":"电路","qt":"填空","pts":5,"ch":"ec-resonance","q":"7. 一个简单并联谐振电路如图7(a)所示 [图7(a)：并联谐振电路]，已知 $L=100\\,\\mu H$，无载品质因数 $Q_0=100$，该电路在频率 $f_0=2\\,MHz$ 发生谐振。现欲将带宽改变为 $B=40\\,kHz$，则如图7(b) [图7(b)：并联电阻 $R$ 后] 需要在电路中并联一个电阻 $R=$ ____。","img":"pro-img/2021_p07.jpg","a":"$40\\pi\\,k\\Omega$","s":"解析：$R_0=2\\pi f_0Q_0L=40\\pi\\,k\\Omega$；负载 $Q=\\dfrac{f_0}{B}=\\dfrac{2\\times10^6}{40\\times10^3}=50$，$R_{总}=50\\omega_0L=20\\pi\\,k\\Omega$；$R_{总}=R_0//R$，得 $R=40\\pi\\,k\\Omega$。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r21-21","seq":21,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"8. 电路如图8所示 [图8：耦合电感电路，$k=1$，$L_1=L_2=3H$]，若 $U_1=6\\angle0^\\circ V$，角频率 $\\omega=2\\,rad/s$，则 $U_2=$ ____。","img":"pro-img/2021_p07.jpg","a":"$3\\sqrt{2}\\angle45^\\circ\\,V$","s":"解析：$M=k\\sqrt{L_1L_2}=3\\,H$，去耦等效后 $U_2=\\dfrac{j6}{6+j6}\\times6\\angle0^\\circ=3\\sqrt{2}\\angle45^\\circ\\,V$。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r21-22","seq":22,"part":"电路","qt":"填空","pts":5,"ch":"ec-twoport","q":"9. 如图9所示的二端口网络 [图9：含 $R$、$C$ 的二端口网络] 的 Z 参数为____。","img":"pro-img/2021_p07.jpg","a":"$Z=\\begin{bmatrix}R+\\tfrac{1}{j\\omega C}&\\tfrac{1}{j\\omega C}\\\\\\tfrac{1}{j\\omega C}&\\tfrac{1}{j\\omega C}\\end{bmatrix}$（原文 OCR 存疑）","s":"解析：由电路列 Z 参数（解析 OCR 残缺，图9 见原卷）。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r21-23","seq":23,"part":"电路","qt":"解答","pts":8,"ch":"ec-analyze","q":"1.（8分）图10所示电阻电路 [图10：含 $2\\,A$ 电流源、$4\\,V$ 电压源与电阻的电路]，已知二端网络 N 吸收的功率 $P=2\\,W$，求电压 $u$。","img":"pro-img/2021_p08.jpg","a":"$u=1\\,V$ 或 $u=2\\,V$","s":"解析：由 KCL、KVL 得 $u=3-i$；又 $p=ui=2$，即 $u(3-u)=2$，$u^2-3u+2=0$，解得 $u=1\\,V$ 或 $u=2\\,V$。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r21-24","seq":24,"part":"电路","qt":"解答","pts":8,"ch":"ec-sinusoidal","q":"2.（8分）如图11所示电路 [图11：$L$、$C$ 支路串联电阻均为 $R$ 的电路]，电感 $L$ 与电容 $C$ 所在支路的串联电阻均为 $R$。（1）当 $R$ 满足何种条件时，输入阻抗 $Z_{in}(j\\omega)=U/I$ 与 $\\omega$ 无关？（2）当输入阻抗与 $\\omega$ 无关时，若以电容所在支路的电阻电压 $U_c$ 为输出，求出此时电路的传输函数 $H(j\\omega)$ 以及相应的截止频率。","img":"pro-img/2021_p08.jpg","a":"（1）$R=\\sqrt{\\dfrac{L}{C}}$（即 $R^2=\\dfrac{L}{C}$）；（2）$H(j\\omega)=\\dfrac{U_c}{U}=\\dfrac{j\\omega RC}{1+j\\omega RC}$，截止角频率 $\\omega_c=\\dfrac{1}{RC}$（$f_c=\\dfrac{1}{2\\pi RC}$）","s":"解析：$Z_{in}=(R+j\\omega L)//\\left(R+\\tfrac{1}{j\\omega C}\\right)=\\dfrac{(R+j\\omega L)(R+\\tfrac{1}{j\\omega C})}{2R+j\\omega L+\\tfrac{1}{j\\omega C}}$；当 $R^2=\\tfrac{L}{C}$ 时 $Z_{in}=R$ 与 $\\omega$ 无关；$H(j\\omega)=\\dfrac{R}{R+\\tfrac{1}{j\\omega C}}=\\dfrac{j\\omega RC}{1+j\\omega RC}$。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r21-25","seq":25,"part":"电路","qt":"解答","pts":8,"ch":"ec-dynamic","q":"3.（8分）电路如图12所示 [图12：含开关、$12\\,V$ 源、$0.5i$ 受控源与 $0.5\\,F$ 电容的电路]，当 $t<0$ 时，开关 S 断开且电路处于稳态，当 $t=0$ 时闭合开关，试求出 $t\\ge0$ 时电流 $i(t)$。","img":"pro-img/2021_p08.jpg","a":"$i(t)=3+e^{-2t}\\,A,\\ t\\ge0$（$u_c(t)=6+2e^{-2t}\\,V$）","s":"解析：对电容以左部分作戴维南等效，$U_{oc}=12\\,V$，$R_{eq}=2\\,\\Omega$；$u_c(0_+)=u_c(0_-)=\\tfrac{2+2}{2+2+2}\\times12=8\\,V$；稳态 $u_c(\\infty)=\\tfrac{2}{2+2}\\times12=6\\,V$；$\\tau=RC=1\\times0.5=0.5\\,s$；故 $u_c(t)=6+2e^{-2t}\\,V$，$i(t)=\\tfrac{u_c(t)}{2}=3+e^{-2t}\\,A$。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r21-26","seq":26,"part":"电路","qt":"解答","pts":6,"ch":"ec-sinusoidal","q":"4.（6分）电路如图13所示 [图13：耦合电感电路]，已知 $u_s=2\\sqrt2\\cos(2t+45^\\circ)\\,V$，$L_1=L_2=1.5\\,H$，$M=0.5\\,H$，$C=0.25\\,F$，负载电阻 $R_L=1\\,\\Omega$。求 $R_L$ 上流过的电流 $i_2(t)$。","img":"pro-img/2021_p08.jpg","a":"$i_2(t)=2\\sqrt2\\cos(2t-135^\\circ)\\,A$","s":"解析：$\\omega=2$，去耦等效得 $j\\omega(L_1-M)=j2\\,\\Omega$、$j\\omega M=j1\\,\\Omega$、$j\\omega(L_2-M)=j2\\,\\Omega$、$\\tfrac{1}{j\\omega C}=-j2\\,\\Omega$；$U_s=2\\angle45^\\circ\\,V$，$I_2=\\dfrac{(1+j2)//(j1-j2)}{(1+j2)//(j1-j2)+j2}\\cdot\\dfrac{U_s}{1+j2}=2\\angle-135^\\circ\\,A$，故 $i_2(t)=2\\sqrt2\\cos(2t-135^\\circ)\\,A$。","t":"真题","y":2021,"src":"西电8112021真题"},{"id":"r22-13","seq":13,"part":"电路","qt":"填空","pts":5,"ch":"ec-basic","q":"如图1所示电路，已知 $U=3$ V，求电阻 $R$。[图1：含电阻及受控源的电路，已知电压 $U=3$ V，求 $R$]","img":"pro-img/2022_p05.jpg","a":"$R=2\\,\\text{k}\\Omega$","s":"","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r22-14","seq":14,"part":"电路","qt":"填空","pts":5,"ch":"ec-basic","q":"如图2所示电路，求电流 $i$ 和电流源产生的功率 $P$。[图2：含 $2\\text{k}\\Omega$ 电阻、$6$ A 电流源、$10$ V 电压源的电路]","img":"pro-img/2022_p06.jpg","a":"$i=1$ A（功率 $P$ 答案页未清晰给出，以答案页为准）","s":"","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r22-15","seq":15,"part":"电路","qt":"填空","pts":5,"ch":"ec-dynamic","q":"如图3所示电路已处于稳态，$t=0$ 时开关 $S$ 开启，求初始值 $i(0_+)$、$u(0_+)$。[图3：含 $0.5$ F 电容、$6\\Omega$、$2\\text{mH}$ 等元件的一阶电路]","img":"pro-img/2022_p06.jpg","a":"$i(0_+)=\\dfrac32$ A，$u(0_+)=-3$ V","s":"","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r22-16","seq":16,"part":"电路","qt":"填空","pts":5,"ch":"ec-resonance","q":"如图4所示电路为并联谐振电路，求品质因数 $Q$。[图4：并联谐振电路，含 $50\\text{k}\\Omega$、$100\\text{pF}$、$100\\mu$H 等元件]","img":"pro-img/2022_p06.jpg","a":"$Q=40$","s":"","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r22-17","seq":17,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"如图5所示电路，设安培计内阻为零，试求正弦电流 $i$ 的有效值 $I$。[图5：含 $8$ mA、$4$ mA、$5$ mA 电流源的电路]","img":"pro-img/2022_p06.jpg","a":"$I=5$ mA","s":"","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r22-18","seq":18,"part":"电路","qt":"填空","pts":5,"ch":"ec-twoport","q":"求如图6所示二端口电路的 $H$ 参数矩阵。[图6：二端口电路]","img":"pro-img/2022_p06.jpg","a":"$\\boldsymbol{H}=\\begin{bmatrix}1&5\\\\2&1\\end{bmatrix}$（$h_{11}=1\\Omega$，$h_{12}=5$，$h_{21}=2$，$h_{22}=1$ S；具体数值以答案页为准）","s":"","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r22-19","seq":19,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"如图7所示两个有损耗的线圈作串联连接，它们之间存在互感，通过测量电流和功率能够确定这两个线圈之间的互感量。现在将频率为 $50$ Hz、电压有效值为 $60$ V 的电源，加在串联线圈两端进行实验。当两线圈顺接（即异名端相连）时，如图(a)，测得电流有效值为 $2$ A，平均功率为 $96$ W；当两线圈反接（即同名端相连）时，如图(b)，测得电流为 $2.4$ A。试确定该两线圈间的互感值 $M$。[图7：(a) 顺接；(b) 反接；两线圈串联]","img":"pro-img/2022_p07.jpg","a":"$M=\\dfrac{11}{400\\pi}$ H","s":"","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r22-20","seq":20,"part":"电路","qt":"填空","pts":5,"ch":"ec-dynamic","q":"如图8所示电路，$N$ 中不含储能元件，当 $t=0$ 时开关闭合，输出电压的零状态响应为 $u_o(t)=1+e^{-t}$ V，$t\\ge0$。如果将 $2$ F 的电容换为 $2$ H 的电感，求输出电压的零状态响应 $u_o(t)$。[图8：含无源电阻网络 $N$、$2$ F 电容（或 $2$ H 电感）、$jX_L$、$jX_{r2}$ 的电路]","img":"pro-img/2022_p07.jpg","a":"$u_o(t)=2-e^{-t}$ V，$t\\ge0$","s":"","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r22-21","seq":21,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"如图9所示电路，已知 $R_1=10\\Omega$，$R_2=2\\Omega$，$X_1=3\\Omega$，$X_2=8\\Omega$，$X_m=10\\Omega$，$U_s=100$ V，若 $Z_L$ 为纯电阻 $R_L$，为使其获得最大功率，$Z_L$ 应取何值？[图9：含互感耦合（$jX_1$、$jX_2$、$jX_m$）的电路]","img":"pro-img/2022_p07.jpg","a":"$Z_L=R_L=34\\Omega$","s":"","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r22-22","seq":22,"part":"电路","qt":"解答","pts":7,"ch":"ec-analyze","q":"（7分）如图10所示电路，负载电阻 $R_L$ 可任意改变，问 $R_L$ 为何值时其上可获得最大功率，并求出该最大功率 $P_{max}$。[图10：含 $4\\Omega$、$2\\Omega$ 电阻及电源的电路]","img":"pro-img/2022_p08.jpg","a":"$R_L=3\\Omega$ 时获得最大功率，$P_{max}=48$ W","s":"由叠加定理得开路电压 $U_{OC}=24$ V；等效电阻 $R_0=3\\Omega$；当 $R_L=R_0=3\\Omega$ 时获最大功率，$P_{max}=\\dfrac{U_{OC}^2}{4R_L}=\\dfrac{24^2}{4\\times3}=48$ W。","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r22-23","seq":23,"part":"电路","qt":"解答","pts":8,"ch":"ec-dynamic","q":"（8分）如图11所示电路，$t=0$ 时开关 $S$ 开启，开启前电路已处于稳态，求 $t\\ge0$ 时电流 $i_L$ 和 $i$ 的零输入响应、零状态响应和全响应。[图11：含 $6\\Omega$、$3\\Omega$、$2$ H 电感、$3$ A 电流源的电路]","img":"pro-img/2022_p08.jpg","a":"$i_L$：零输入响应 $e^{-9t/2}$ A，零状态响应 $1-e^{-9t/2}$ A，全响应 $1$ A；$i$：零输入响应 $-e^{-9t/2}$ A，零状态响应 $2+e^{-9t/2}$ A，全响应 $2$ A（$t\\ge0$）。","s":"由换路定则 $i_L(0_+)=i_L(0_-)=1$ A；稳态 $i_L(\\infty)=1$ A；时间常数 $\\tau=\\frac{L}{R}=\\frac{2}{3+6}=\\frac29$ s。$i_{Lzi}(t)=e^{-9t/2}$ A，$i_{Lzs}(t)=1-e^{-9t/2}$ A，$i_L(t)=1$ A；$i(t)=3-i_L(t)$，故 $i_{zi}(t)=-e^{-9t/2}$ A，$i_{zs}(t)=3-(1-e^{-9t/2})=2+e^{-9t/2}$ A，$i(t)=2$ A。","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r22-24","seq":24,"part":"电路","qt":"解答","pts":8,"ch":"ec-twoport","q":"（8分）如图12所示电路，$N$ 为线性无源二端电阻电路，$U_s=20$ V。已知 $R=\\infty$ 时，$I_1=0.4$ A，$U_2=8$ V；当 $R=0$，$I_1=1$ A，$I_2=-1$ A。求当 $R=4\\Omega$ 时 $I_1$、$I_2$ 的值。[图12：含二端口网络 $N$、可变电阻 $R$ 的电路]","img":"pro-img/2022_p08.jpg","a":"$I_1=\\dfrac45$ A，$I_2=-\\dfrac23$ A","s":"设 $\\boldsymbol{Z}=\\begin{bmatrix}Z_{11}&Z_{12}\\\\Z_{21}&Z_{22}\\end{bmatrix}$，$U_1=Z_{11}I_1+Z_{12}I_2$，$U_2=Z_{21}I_1+Z_{22}I_2$。$R=\\infty$（$I_2=0$）：$20=0.4Z_{11}\\Rightarrow Z_{11}=50\\Omega$，$8=0.4Z_{21}\\Rightarrow Z_{21}=20\\Omega$。$R=0$（$U_2=0$）：$20=50\\times1-Z_{12}\\Rightarrow Z_{12}=30\\Omega$，$0=20\\times1-Z_{22}\\Rightarrow Z_{22}=20\\Omega$。$R=4\\Omega$ 时 $U_2=-4I_2=20I_1+20I_2$，$20=50I_1+30I_2$，解得 $I_1=\\frac45$ A，$I_2=-\\frac23$ A。","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r22-25","seq":25,"part":"电路","qt":"解答","pts":7,"ch":"ec-sinusoidal","q":"（7分）如图13所示正弦稳态电路，已知 $C=100$ pF，$L=100\\mu$H，电路消耗功率 $P=100$ mW，电流 $i_C(t)=10\\sqrt2\\cos(10^7t+60^\\circ)$ mA，试求电阻 $R$ 和电压 $u(t)$。[图13：含 $R$、$C$、$L$ 的正弦稳态电路]","img":"pro-img/2022_p09.jpg","a":"$R=1\\,\\text{k}\\Omega$；$u(t)=10\\sqrt2\\cos(10^7t+60^\\circ)$ V","s":"$\\omega=10^7$，$X_L=\\omega L=1\\text{k}\\Omega$，$X_C=\\frac{1}{\\omega C}=1\\text{k}\\Omega$。$\\dot I_C=10\\angle60^\\circ$ mA，$\\dot U_C=-j1000\\dot I_C=10\\angle-30^\\circ$ V。$R=\\frac{U_C^2}{P}=\\frac{10^2}{0.1}=1\\text{k}\\Omega$；$\\dot I_R=\\frac{\\dot U_C}{R}=10\\angle-30^\\circ$ mA；$\\dot I=\\dot I_C+\\dot I_R=10\\sqrt2\\angle15^\\circ$ mA；$\\dot U_L=j1000\\dot I=10\\sqrt2\\angle105^\\circ$ V；$\\dot U=\\dot U_L+\\dot U_C=10\\angle60^\\circ$ V，故 $u(t)=10\\sqrt2\\cos(10^7t+60^\\circ)$ V。","t":"真题","y":2022,"src":"西电8112022真题"},{"id":"r23-15","seq":15,"part":"电路","qt":"填空","pts":5,"ch":"ec-basic","q":"电路如图1所示，求受控源端电压 $u$。[图1：含 2Ω 电阻与受控源的电路（原文不清，见整页图）]","img":"pro-img/2023_p05.jpg","a":"4 V","s":"设中间 2Ω 电阻电流为 $i_1$（方向向下），据图列方程解得 $i_1=2\\ \\mathrm{A}$，$u=2i_1=4\\ \\mathrm{V}$（原文解析不清）。","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"r23-16","seq":16,"part":"电路","qt":"填空","pts":5,"ch":"ec-twoport","q":"如图2所示电路，已知 $i_s=6\\angle0°\\ \\mathrm{A}$，二端口网络 Y 参数矩阵 $Y=\\begin{bmatrix}0.5&-0.3\\\\-0.3&0.7\\end{bmatrix}$，$R_L=5\\ \\Omega$，计算负载 $R_L$ 吸收的功率。[图2：电流源→Y 参数二端口→负载 $R_L$]","img":"pro-img/2023_p05.jpg","a":"5 W","s":"二端口方程 $I_1=0.5U_1-0.3U_2$，$I_2=-0.3U_1+0.7U_2$；端口 1 接 $i_s=6\\ \\mathrm{A}$，端口 2 接 $R_L=5\\Omega$。解得负载电流 $1\\ \\mathrm{A}$，$P=I^2R_L=1^2\\times5=5\\ \\mathrm{W}$。","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"r23-17","seq":17,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"如图3所示电路，N 为无源线性网络，独立源 $u_{s1},u_{s2},i_s$ 的数值一定。当 $i_s$ 与 $u_{s1}$ 反向、$u_{s2}$ 不变时，$u_o$ 是原来的 0.5 倍；当 $i_s$ 与 $u_{s2}$ 反向、$u_{s1}$ 不变时，$u_o$ 是原来的 0.3 倍；当 $i_s$ 反向，而 $u_{s1},u_{s2}$ 不变时，$u_o$ 是原来的多少倍？[图3：无源线性网络 N 与三独立源]","img":"pro-img/2023_p06.jpg","a":"1.8 倍","s":"由叠加定理 $u_o=au_{s1}+bu_{s2}+ci_s$。令 $A=au_{s1},B=bu_{s2},C=ci_s$，据题意 $-A+B-C=0.5u_o$，$A-B-C=0.3u_o$，联立解得 $B=3A+3C$、$C=-\\frac{8}{13}A$，故 $\\frac{A+B-C}{A+B+C}=\\frac{9}{5}=1.8$。","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"r23-18","seq":18,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"如图4所示电路，已知 $U=10\\angle0°\\ \\mathrm{V}$，$Z_L$ 可任意改变，求其上可获得的最大功率。[图4：电压源、10Ω、j5Ω 与负载 $Z_L$（原文不清，以图为准）]","img":"pro-img/2023_p06.jpg","a":"2.5 W（当 $Z_L=Z_{th}^{*}=10-j5\\ \\Omega$ 时）","s":"戴维南等效 $U_{oc}=10\\angle0°\\ \\mathrm{V}$，$Z_{th}=10+j5\\ \\Omega$（原文不清，以图为准），$P_{max}=\\frac{|U_{oc}|^2}{4\\mathrm{Re}[Z_{th}]}=\\frac{100}{4\\times10}=2.5\\ \\mathrm{W}$。","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"r23-19","seq":19,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"如图5所示电路，求电压 $u$。[图5：含 2Ω、1.5Ω 电阻、7A 电流源与受控源的电路]","img":"pro-img/2023_p06.jpg","a":"2 V","s":"节点/网孔分析（原文解析不清，结果为 $u=2\\ \\mathrm{V}$）。","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"r23-20","seq":20,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"求如图6所示电路中的电压 $u$。[图6：含 15V 源、3kΩ、2kΩ、4kΩ、$\\beta u$ 受控源、-4V 源的电路]","img":"pro-img/2023_p06.jpg","a":"原文不清（答案页未识别到该题结果）","s":"","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"r23-21","seq":21,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"如图7所示电路，负载 $R_L$ 为何值时能获得最大功率？[图7：含 12Ω、4Ω、6Ω、$2i$ 受控源与 $R_L$ 的电路]","img":"pro-img/2023_p07.jpg","a":"$R_L=6\\ \\Omega$","s":"加压源求端口等效电阻 $R_o$，据 KCL/KVL 得 $R_o=6\\ \\Omega$，故 $R_L=R_o=6\\ \\Omega$ 时获最大功率。","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"r23-22","seq":22,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"如图8所示电路，已知 $U_s=20\\angle0°\\ \\mathrm{V}$，求 $I$。[图8：含理想变压器 2:1、12Ω、1Ω、$2i$ 受控源的电路]","img":"pro-img/2023_p07.jpg","a":"原文不清（答案页 OCR 疑似「2.4∠84° A」，角度存疑）","s":"设理想变压器原边电流为 $i$（方向向左），由变流比与 KVL 求解（原文解析不清）。","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"r23-23","seq":23,"part":"电路","qt":"填空","pts":5,"ch":"ec-twoport","q":"求如图9所示二端口电路的 Z 参数矩阵。[图9：含 5Ω 元件的二端口网络]","img":"pro-img/2023_p07.jpg","a":"原文不清（图9 结构不明，Z 参数无法唯一确定）","s":"","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"r23-24","seq":24,"part":"电路","qt":"解答","pts":6,"ch":"ec-analyze","q":"如图10所示电路，求电流 $i$ 和电压 $u_x$。[图10：3A 源、1Ω、2Ω、3Ω、4Ω 与受控源 $1.9i$ 的电路]","img":"pro-img/2023_p07.jpg","a":"$u_x=3\\ \\mathrm{V}$；$i$ 原文不清","s":"（答案页仅识别到「解得 3V」，其余解析不清。）","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"r23-25","seq":25,"part":"电路","qt":"解答","pts":10,"ch":"ec-dynamic","q":"如图11所示电路，开关 S 闭合到 1 的位置，电路处于稳态，$t=0$ 时，开关 S 闭合到 2 的位置，求 $t\\ge0$ 时 $u(t)$ 的零输入响应和零状态响应。[图11：6A 源、12V 源、三个 6Ω 电阻与 3H 电感]","img":"pro-img/2023_p07.jpg","a":"原文不清（一阶 RL 电路，$L=3\\ \\mathrm{H}$，时间常数 $\\tau=L/R$；零输入响应含 $e^{-\\frac{R}{3}t}$ 型项，答案页解析不清）","s":"由 $t=0_-$ 稳态与换路定则求 $i_L(0_+)$，再按一阶三要素法求零输入/零状态响应（原文解析不清）。","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"r23-26","seq":26,"part":"电路","qt":"解答","pts":7,"ch":"ec-sinusoidal","q":"如图12所示正弦稳态电路，已知 $\\omega L_1=5\\ \\Omega$，$\\omega L_2=15\\ \\Omega$，$\\omega L_3=10\\ \\Omega$，$M=2\\ \\Omega$，$\\omega L=20\\ \\Omega$，$R=5\\ \\Omega$，求 $i_s(t)=10+10\\cos(\\omega t)+10\\cos(2\\omega t)\\ \\mathrm{mA}$ 时的电压 $u(t)$。[图12：耦合电感正弦稳态电路]","img":"pro-img/2023_p08.jpg","a":"$u(t)=6\\cos(\\omega t)\\ \\mathrm{V}$","s":"直流分量（10 mA）时电感短路，$u=0$。$10\\cos(\\omega t)$ 分量时去耦等效（$j13\\Omega,j8\\Omega$ 等）得 $u=6\\cos(\\omega t)\\ \\mathrm{V}$。$10\\cos(2\\omega t)$ 分量时发生串联谐振、支路短路，$u=0$。叠加得 $u(t)=6\\cos(\\omega t)\\ \\mathrm{V}$。","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"r23-27","seq":27,"part":"电路","qt":"解答","pts":7,"ch":"ec-resonance","q":"如图13所示正弦稳态电路，已知 $U=100\\angle0°\\ \\mathrm{mV}$，$\\omega L_1=\\omega L_2=10\\ \\Omega$，$\\omega M=6\\ \\Omega$，$\\omega=10^6\\ \\mathrm{rad/s}$，求 $C$ 为何值时 $i=0$，并计算此时 $i_1=?$。[图13：耦合电感与电容的并联谐振电路]","img":"pro-img/2023_p08.jpg","a":"$C=0.5\\ \\mu\\mathrm{F}$；$i_1=2.5\\angle-90°\\ \\mathrm{mA}$（原文不清，角度存疑）","s":"去耦等效后，当电容支路与等效电感发生并联谐振时 $i=0$，解得 $C=0.5\\ \\mu\\mathrm{F}$，此时 $i_1=2.5\\angle-90°\\ \\mathrm{mA}$（原文解析不清）。","t":"真题","y":2023,"src":"西电8112023真题"},{"id":"fc15-01","seq":1,"part":"电路","qt":"选择","pts":3,"ch":"ec-basic","q":"如题1图所示电路，已知 $I=1$ A，$U=6$ V，则（ ）。[题1图：元件 A、B 连接，电流 I=1 A，电压 U=6 V]","o":["A. A吸收功率，B发出功率","B. A发出功率，B吸收功率","C. A发出功率，B发出功率","D. A吸收功率，B吸收功率"],"img":"pro-img/final-ec_p19.jpg","a":"B","s":"","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-02","seq":2,"part":"电路","qt":"选择","pts":3,"ch":"ec-basic","q":"如题2图所示电路，电流 $I$ 等于（ ）。[题2图：含 2 A 电流源与电阻网络的电路]","o":["A. 1A","B. 2A","C. 3A","D. 4A"],"img":"pro-img/final-ec_p19.jpg","a":"A","s":"","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-03","seq":3,"part":"电路","qt":"选择","pts":3,"ch":"ec-basic","q":"如题3图所示电路，电流 $I$ 等于（ ）。[题3图：含电压源与电阻的电路]","o":["A. 2A","B. 4A","C. 6A","D. 8A"],"img":"pro-img/final-ec_p19.jpg","a":"C","s":"","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-04","seq":4,"part":"电路","qt":"选择","pts":3,"ch":"ec-sinusoidal","q":"如题4图所示电路，已知 $U_R=12$ V，$U_C=5$ V，则 $U$ 等于（ ）。[题4图：R、C 串联电路，U_R=12 V，U_C=5 V]","o":["A. 17V","B. 13V","C. 7V","D. -7V"],"img":"pro-img/final-ec_p19.jpg","a":"B","s":"","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-05","seq":5,"part":"电路","qt":"选择","pts":3,"ch":"ec-dynamic","q":"如题5图所示电路，$t<0$ 时开关闭合，电路已达稳态，$t=0$ 时开关 S 打开，则 $i(0_+)=$（ ）。[题5图：10 V 电压源、电阻、2 F 电容与开关 S]","o":["A. -1A","B. 1A","C. 0.5A","D. -0.5A"],"img":"pro-img/final-ec_p20.jpg","a":"C","s":"换路瞬间电容电压不跳变，$u_C(0_+)=u_C(0_-)=15$ V，$u_C(\\infty)=10$ V，$\\tau=RC=20$ s；由三要素法 $u_C(t)=10+5e^{-t/20}$ V，$i(t)=C\\frac{du_C}{dt}$，得 $i(0_+)=0.5$ A。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-06","seq":6,"part":"电路","qt":"选择","pts":3,"ch":"ec-sinusoidal","q":"如题6图所示电路，电压 $U$ 等于（ ）。[题6图：理想变压器 1:2，一次侧接 $4\\angle0°$ A 电流源与 1 Ω 电阻]","o":["A. 8V","B. -8V","C. 16V","D. 0V"],"img":"pro-img/final-ec_p20.jpg","a":"B","s":"根据同名端可得 $U<0$，电流比为变比的倒数 $I_1:I_2=2:1$，故 $I_2=2\\angle0°$ A，$U=-4I_1=-8$ V。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-07","seq":7,"part":"电路","qt":"选择","pts":3,"ch":"ec-sinusoidal","q":"如题7图所示电路，电流 $I$ 等于（ ）。[题7图：理想变压器 2:1，一次侧接 $4\\angle0°$ A 电流源，二次侧短路]","o":["A. 0.5A","B. 1A","C. 2A","D. 8A"],"img":"pro-img/final-ec_p20.jpg","a":"D","s":"变压器输出端负载为 0，故输入端等效阻抗也为 0，$I_1=4\\angle0°$ A；由 $N_1:N_2=2:1$ 得 $I_1:I_2=1:2$，$I_2=8\\angle0°$ A，$I=8$ A。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-08","seq":8,"part":"电路","qt":"选择","pts":3,"ch":"ec-sinusoidal","q":"如题8图所示电路，已知 $i_{s1}(t)=e^t$ A，$i_{s2}(t)=2e^t$ A，则 $u(t)$ 等于（ ）。[题8图：耦合电感（2 H、4 H、3 H）与电流源 $i_{s1}$、$i_{s2}$]","o":["A. $4e^t$","B. $5e^t$","C. $6e^t$","D. $8e^t$"],"img":"pro-img/final-ec_p20.jpg","a":"A","s":"耦合电感感应电压叠加，$u(t)=u_s(t)-u_m(t)=4e^t$ V。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-09","seq":9,"part":"电路","qt":"选择","pts":3,"ch":"ec-resonance","q":"如题9图所示谐振电路，品质因数 $Q$ 和谐振角频率 $\\omega_0$ 等于（ ）。[题9图：RLC 串联谐振电路，R=2 Ω，L=200 mH，C=20 μF]","o":["A. $50;250$ rad/s","B. $50;500$ rad/s","C. $200;250$ rad/s","D. $200;500$ rad/s"],"img":"pro-img/final-ec_p20.jpg","a":"B","s":"$\\omega_0=\\dfrac{1}{\\sqrt{LC}}=\\dfrac{1}{\\sqrt{0.2\\times20\\times10^{-6}}}=500$ rad/s；$Q=\\dfrac{\\omega_0 L}{R}=\\dfrac{500\\times0.2}{2}=50$。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-10","seq":10,"part":"电路","qt":"选择","pts":3,"ch":"ec-sinusoidal","q":"如题10图所示正弦稳态电路，$U=10\\angle0°$ V，功率因数为 0.6，电路吸收功率 $P=12$ W，则 $R=$（ ）。[题10图：正弦稳态电路，含电阻 R 与电抗元件]","o":["A. 1Ω","B. 2Ω","C. 3Ω","D. 4Ω"],"img":"pro-img/final-ec_p21.jpg","a":"C","s":"$\\cos\\varphi=0.6$，$P=12$ W，$\\varphi<0$ 故 $\\sin\\varphi=-0.8$；$I=\\dfrac{P}{U\\cos\\varphi}=\\dfrac{12}{10\\times0.6}=2$ A（$\\angle-37°$），由 $I^2R=P$ 得 $R=3$ Ω。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-11","seq":11,"part":"电路","qt":"填空","pts":4,"ch":"ec-analyze","q":"如题11图所示电路，ab 端等效电阻 $R_{ab}=$（ ）。[题11图：电阻（电导）网络，ab 端口]","img":"pro-img/final-ec_p21.jpg","a":"20Ω","s":"","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-12","seq":12,"part":"电路","qt":"填空","pts":4,"ch":"ec-twoport","q":"如题12图所示二端口电路中，N 的 Y 参数矩阵 $Y$（$I_1=j0.5U_1+j0.5U_2$），$U_s=10$ V，$R=4$ Ω，则 R 上吸收的功率 $P=$（ ）。[题12图：二端口网络 N 与电阻 R=4 Ω]","img":"pro-img/final-ec_p21.jpg","a":"20W","s":"由 Y 参数矩阵得 $I_1=j0.5U_1+j0.5U_2$，$U_1=10\\angle0°$ V，解得 $(1+j2)I_1=5\\angle90°$，故 $I_1=\\sqrt5$ A，$P=I_1^2R=(\\sqrt5)^2\\times4=20$ W。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-13","seq":13,"part":"电路","qt":"填空","pts":4,"ch":"ec-sinusoidal","q":"如题13图正弦稳态电路，$u(t)=5\\sin2t$ V，$i(t)=\\sqrt2\\cos(2t-45°)$ A，则 $R=$（ ），$C=$（ ）。[题13图：R 与 C 并联电路]","img":"pro-img/final-ec_p21.jpg","a":"$R=5$ Ω；$C=0.1$ F","s":"$\\omega=2$，$U=\\frac{5}{\\sqrt2}\\angle0°$，$I=1\\angle45°$ A，故 $Z=\\frac{U}{I}=2.5-j2.5$ Ω；RC 并联 $Z=\\frac{R}{1+j\\omega RC}$，解得 $R=5$ Ω，$C=0.1$ F。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-14","seq":14,"part":"电路","qt":"填空","pts":4,"ch":"ec-sinusoidal","q":"如题14图所示正弦稳态电路，已知 $U=5\\angle0°$ V，则电路中的 $P=$（ ），$Q=$（ ）。[题14图：含 3 Ω、4 Ω、-j3 Ω、2 Ω 等阻抗的正弦稳态电路]","img":"pro-img/final-ec_p21.jpg","a":"P=7W；Q=1var","s":"注意这里的 $Q$ 是无功功率而不是品质因数。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-15","seq":15,"part":"电路","qt":"填空","pts":4,"ch":"ec-dynamic","q":"如题15图所示电路，$t<0$ 时电路已达稳态，$t=0$ 时开关 S 闭合，则 $u(0_+)=$（ ）。[题15图：10 V 电压源、电阻、1 F 电容与开关 S]","img":"pro-img/final-ec_p22.jpg","a":"10V","s":"有调谐电阻，电容两端电压不能跳变，$u_C(0_+)=u_C(0_-)=0$ V，$u(0_+)=10$ V。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-16","seq":16,"part":"电路","qt":"解答","pts":10,"ch":"ec-analyze","q":"如题16图所示电路，调节可变电阻 $R$，使得 $U=6$ V，求电阻 $R$ 的值。[题16图：12 V 电压源、若干电阻与可变电阻 R]","img":"pro-img/final-ec_p22.jpg","a":"$R=8$ Ω","s":"由 $U=6$ V 得 $I_{R1}=3$ A；由 KVL 得 $U_{R4}+U=12$，故 $U_{R4}=6$ V，$I_{R4}=2$ A；由 KCL 得 $I_{R2}=I_{R1}-I_{R4}=1$ A，$U_{R2}=2$ V，$U_{R3}=12-U-U_{R2}=4$ V，$I_{R3}=2$ A，$I_R=1$ A；故 $U_R=12-U_{R3}=8$ V，$R=\\frac{U_R}{I_R}=8$ Ω。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-17","seq":17,"part":"电路","qt":"解答","pts":10,"ch":"ec-dynamic","q":"如题17图所示电路，$t<0$ 时开关 S 打开，电路已达稳态，$t=0$ 时开关 S 闭合，求 $t\\ge0$ 时的电压 $u(t)$，并画出其波形。[题17图：20 V 电压源、电阻、0.5 H 电感与开关 S]","img":"pro-img/final-ec_p22.jpg","a":"$u(t)=16e^{-2t}$ V（$t\\ge0$）","s":"$t<0$ 时 $i(0_-)=4$ A $=i(0_+)$；闭合后 $u(0_+)=20-i(0_+)=16$ V，$u(\\infty)=0$，$\\tau=\\frac{L}{R}=0.5$ s；由三要素法 $u(t)=u(\\infty)+[u(0_+)-u(\\infty)]e^{-t/\\tau}=16e^{-2t}$ V。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-18","seq":18,"part":"电路","qt":"解答","pts":10,"ch":"ec-sinusoidal","q":"如题18图所示正弦稳态电路，已知 $u(t)=100\\cos(10^3t+75°)$ V，$i(t)=10\\sqrt2\\cos(10^3t+30°)$ A，$L=5$ mH，求电流 $i_C(t)$。[题18图：R、L、C 正弦稳态电路]","img":"pro-img/final-ec_p23.jpg","a":"$i_C(t)=10\\cos(10^3t+165°)$ A","s":"$\\omega=10^3$，$\\omega L=5$ Ω；以 $u(t)$ 为参考相量，$U=50\\sqrt2\\angle0°$，$I=10\\angle45°=5\\sqrt2-j5\\sqrt2$ A；由相量关系得 $i_L+i_C=-j5\\sqrt2$ A，故 $I_C=5\\sqrt2\\angle75°$，$i_C(t)=10\\cos(10^3t+165°)$ A。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-19","seq":19,"part":"电路","qt":"解答","pts":10,"ch":"ec-analyze","q":"如题19图所示正弦稳态电路，已知 $U=6\\angle0°$ V，负载 $Z_L$ 可变。为使 $Z_L$ 获得最大功率，求 $Z_L$ 及其最大功率 $P_{\\max}$。[题19图：含 0.5 Ω、-j Ω 与受控源的正弦稳态电路，负载 $Z_L$ 可变]","img":"pro-img/final-ec_p23.jpg","a":"$Z_L=0.5(1+j)$ Ω；$P_{\\max}=9$ W","s":"戴维南等效：$U_{oc}=0.5(1-j)I_0+3-j3$，令 $I_0=0$ 得 $U_{oc}=3-j3$ V，$Z_0=0.5(1-j)$ Ω；当 $Z_L=Z_0^*=0.5(1+j)$ Ω 时，$P_{\\max}=\\dfrac{|U_{oc}|^2}{4R_0}=\\dfrac{3^2+3^2}{4\\times0.5}=9$ W。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc15-20","seq":20,"part":"电路","qt":"解答","pts":10,"ch":"ec-sinusoidal","q":"如题20图所示正弦稳态电路，已知 $U_s=30\\angle0°$ V，$R_L=16$ Ω，求 $R_L$ 吸收的功率。[题20图：4.5 Ω、j5 Ω、理想变压器 2:1、j10 Ω、j8 Ω 与 $R_L$]","img":"pro-img/final-ec_p24.jpg","a":"$P=2.65$ W","s":"右侧变压器匝数比为 $2:1$，故 $U_1:U_2=2:1$，$I_1:I_2=1:2$；负载折算到一次侧 $R_L'=(N_1/N_2)^2R_L=4\\times16=64$ Ω；由 KVL 求一次侧电流 $I_1$，得 $P=I_1^2R_L'=2.65$ W。","t":"期末","y":2015,"src":"西电电路2015期末"},{"id":"fc16-01","seq":1,"part":"电路","qt":"选择","pts":3,"ch":"ec-basic","q":"基尔霍夫定律的适用范围是（ ）。","o":["A. 集中参数电路","B. 线性非时变电路","C. 分布参数电路","D. 任意电路"],"img":"pro-img/final-ec_p13.jpg","a":"A","s":"KCL 的本质是电荷守恒，KVL 本质是能量守恒，适用于集中参数电路。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-02","seq":2,"part":"电路","qt":"选择","pts":3,"ch":"ec-basic","q":"如题2图所示电路，电流 $I$ 等于（ ）。[题2图：含 10 Ω、5 Ω 电阻与 2 A 电流源的电路]","o":["A. 0A","B. -1A","C. 0.5A","D. 1.5A"],"img":"pro-img/final-ec_p13.jpg","a":"D","s":"由回路电流法列方程 $I_1=I+2$，解得 $I=1.5$ A。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-03","seq":3,"part":"电路","qt":"选择","pts":3,"ch":"ec-basic","q":"如题3图所示电路，电压 $U$ 等于（ ）。[题3图：含 2 A、12 A 电流源与电阻的电路]","o":["A. 2V","B. -2V","C. 4V","D. -4V"],"img":"pro-img/final-ec_p13.jpg","a":"B","s":"选取 1 Ω、1 Ω、2 Ω 电阻所在支路为树支，回路电流法解得 $I_1=2$ A，$I_2=-2$ A，故 $U=1\\cdot I_2=-2$ V。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-04","seq":4,"part":"电路","qt":"选择","pts":3,"ch":"ec-basic","q":"如题4图所示电路，已知 $I=0$ A，则电流 $I_s$ 产生的功率 $P$ 等于（ ）。[题4图：2 V 电压源、电阻与电流源 $I_s$]","o":["A. -4W","B. 4W","C. 2W","D. -2W"],"img":"pro-img/final-ec_p13.jpg","a":"B","s":"$I=0$，由 KVL 得 $2=2\\times0+1\\cdot I_1$，故 $I_1=2$ A，$P=I_1^2R=4$ W；因流经电压源的电流为 0，电压源功率为 0，故 $P_{I_s}=4$ W。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-05","seq":5,"part":"电路","qt":"选择","pts":3,"ch":"ec-analyze","q":"如题5图所示电路，为使 $R_L$ 获得最大功率，则 $R_L$ 等于（ ）。[题5图：2 V 电压源、3 Ω、6 Ω、1 A 电流源与 $R_L$]","o":["A. 2Ω","B. 3Ω","C. 6Ω","D. 12Ω"],"img":"pro-img/final-ec_p14.jpg","a":"A","s":"对 $R_L$ 两端作戴维南等效，等效电阻 $R'=6$ Ω$\\parallel3$ Ω $=2$ Ω。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-06","seq":6,"part":"电路","qt":"选择","pts":3,"ch":"ec-dynamic","q":"如题6图所示电路，$t<0$ 开关 S 打开，电路已处于稳态，$t=0$ 时开关 S 闭合，则 $u(0_+)$ 等于（ ）。[题6图：9 V 电压源、1 Ω、6 Ω、3 Ω、1 H 电感与开关 S]","o":["A. 6V","B. -6V","C. 3V","D. 0V"],"img":"pro-img/final-ec_p14.jpg","a":"B","s":"电感电流不能跳变，$i_L(0_+)=i_L(0_-)=2$ A；$t=0$ 闭合后 $u(0_+)=-u_{3\\Omega}(0_+)=-3\\times2=-6$ V。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-07","seq":7,"part":"电路","qt":"选择","pts":3,"ch":"ec-sinusoidal","q":"如题7图所示电路，已知 $u_s(t)=18\\sqrt2\\cos(100t)$ V，则 $R_L$ 上消耗的平均功率 $P$ 等于（ ）。[题7图：理想变压器 3:1，一次侧 9 Ω，二次侧 $R_L=1$ Ω]","o":["A. 9W","B. 原文不清","C. 2W","D. 1W"],"img":"pro-img/final-ec_p14.jpg","a":"A","s":"$N_1:N_2=3:1$，$U_1:U_2=3:1$，$I_1:I_2=1:3$；负载等效到变压器左边 $R_L'=3^2\\times1=9$ Ω，$U_s=18$ V，故 $I_1=\\frac{18}{9+9}=1$ A，$P=I_1^2R_L'=1^2\\times9=9$ W。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-08","seq":8,"part":"电路","qt":"选择","pts":3,"ch":"ec-resonance","q":"如题8图所示电路，其谐振角频率 $\\omega_0$ 等于（ ）。[题8图：含受控源与 L、C 的谐振电路]","o":["A. $\\frac{1}{\\sqrt{LC}}$","B. $\\frac{1}{\\sqrt{2LC}}$","C. $\\frac{1}{\\sqrt{3LC}}$","D. 原文不清"],"img":"pro-img/final-ec_p14.jpg","a":"C","s":"可将受控源用一个值为 $2C$ 的电容替代，两电容并联后总电容为电容值之和 $3C$，故 $\\omega_0=\\dfrac{1}{\\sqrt{L\\cdot3C}}=\\dfrac{1}{\\sqrt{3LC}}$。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-09","seq":9,"part":"电路","qt":"选择","pts":3,"ch":"ec-sinusoidal","q":"如题9图所示正弦稳态电路中开关 S 闭合和断开时，电压表与电流表读数保持不变，则 $X_L$ 与 $X_C$ 的关系满足（ ）。[题9图：含 $jX_L$、$-jX_C$ 的正弦稳态电路与开关 S]","o":["A. $X_C=2X_L$","B. $X_C=X_L$","C. $X_C=0.5X_L$","D. 无法确定"],"img":"pro-img/final-ec_p15.jpg","a":"C","s":"电压表示数不变，以 $U$ 为参考画相量图，$|\\dot I_R+\\dot I_C+\\dot I_L|=|\\dot I_R+\\dot I_L|$，故 $\\dot I_C=-2\\dot I_L$，$X_C=\\frac{1}{2}X_L$。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-10","seq":10,"part":"电路","qt":"选择","pts":3,"ch":"ec-basic","q":"题10图所示电路，若 $R$、$I_s$、$U_s$ 均大于 0，则电路的功率情况为（ ）。[题10图：电阻 R、电流源 $I_s$、电压源 $U_s$ 构成的电路]","o":["A. 电阻吸收功率，电压源和电流源产生功率","B. 电阻和电压源吸收功率，电流源产生功率","C. 电阻和电流源吸收功率，电压源产生功率","D. 电阻吸收功率，产生功率无法确定"],"img":"pro-img/final-ec_p15.jpg","a":"D","s":"电阻必吸收功率；电压源 $U_s$ 产生或吸收功率情况未知，电流源发出功率。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-11","seq":11,"part":"电路","qt":"填空","pts":4,"ch":"ec-analyze","q":"如题11图所示电路，ab 端等效电阻 $R_{ab}=$（ ）。[题11图：10 Ω、6 Ω、3 Ω 电阻网络]","img":"pro-img/final-ec_p15.jpg","a":"12Ω","s":"右端 3 Ω 电阻直接被短路，无需 Y-Δ 变换，$R_{ab}=10+6\\parallel3=10+2=12$ Ω。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-12","seq":12,"part":"电路","qt":"填空","pts":4,"ch":"ec-twoport","q":"如题12图所示的二端口电路中，其 Z 参数矩阵 $Z=$（ ）。[题12图：含 2 Ω、受控源 $2i_2$、j3 Ω、j4 Ω 的二端口电路]","img":"pro-img/final-ec_p15.jpg","a":"$Z=\\begin{bmatrix}2+j3 & -j2\\\\ j2 & j4\\end{bmatrix}$ Ω","s":"","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-13","seq":13,"part":"电路","qt":"填空","pts":4,"ch":"ec-sinusoidal","q":"如题13图所示正弦稳态电路，$u(t)=7\\cos2t$ V，$i(t)=\\sqrt2\\cos(2t-45°)$ A，则 $R=$（ ），$L=$（ ）。[题13图：R 与 L 并联电路]","img":"pro-img/final-ec_p16.jpg","a":"$R=7$ Ω；$L=3.5$ H","s":"$U=\\frac{7}{\\sqrt2}\\angle0°$ V，$I=1\\angle45°$ A，$\\omega=2$ rad/s；$Y=\\frac{1}{R}-j\\frac{1}{\\omega L}$，解得 $R=7$ Ω，$L=3.5$ H。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-14","seq":14,"part":"电路","qt":"填空","pts":4,"ch":"ec-analyze","q":"如题14图所示电路，设结点 a、b、c 的电位分别为 $U_a$、$U_b$、$U_c$，则结点 c 的电位方程为（ ）。[题14图：4 V 电压源、2 Ω、3 Ω、4 Ω、1 Ω、2 Ω 电阻与 1 A 电流源]","img":"pro-img/final-ec_p16.jpg","a":"","s":"","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-15","seq":15,"part":"电路","qt":"填空","pts":4,"ch":"ec-basic","q":"如题15图所示电路，电压 $U=$（ ）。[题15图：3 A 电流源、4 V 电压源、4 Ω 电阻]","img":"pro-img/final-ec_p16.jpg","a":"8V","s":"","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-16","seq":16,"part":"电路","qt":"解答","pts":10,"ch":"ec-analyze","q":"如题16图所示电路，其电流 $I$ 的值。[题16图：1 A 电流源、6 Ω、6 Ω 电阻与 34 V 电压源]","img":"pro-img/final-ec_p16.jpg","a":"$I=2$ A","s":"设中右两个结点分别为 b、c，列结点电压方程解得 $U_b=14$ V，$U_c=8$ V，故 $I=2$ A。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-17","seq":17,"part":"电路","qt":"解答","pts":10,"ch":"ec-dynamic","q":"如题17图所示电路，$t<0$ 开关 S 打开，电路已处于稳态，$t=0$ 时开关 S 闭合，求 $t\\ge0$ 时的电压 $u(t)$，并画出其波形。[题17图：2 A 电流源、2 Ω、6 Ω、24 V 电压源、0.5 F 电容与开关 S]","img":"pro-img/final-ec_p17.jpg","a":"$u(t)=20-4e^{-t/2}$ V（$t\\ge0$）","s":"$u_C(0_-)=12$ V，稳态 $u_C(\\infty)=20$ V，$\\tau=RC=0.5\\times(2+3\\parallel6)=2$ s；由三要素法 $u_C(t)=20-8e^{-t/2}$ V，$i_C(t)=C\\frac{du_C}{dt}=2e^{-t/2}$ A；故 $u(t)=u_C+2i_C=(20-8e^{-t/2})+4e^{-t/2}=20-4e^{-t/2}$ V。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-18","seq":18,"part":"电路","qt":"解答","pts":10,"ch":"ec-analyze","q":"如题18图电路，已知当开关 S 打开时，$u_{ab}=2.5$ V，当开关 S 闭合时，电流 $I_{ab}=3$ A，求 N 的戴维南等效电路。[题18图：10 V 电压源、5 Ω 电阻、开关 S 与网络 N]","img":"pro-img/final-ec_p17.jpg","a":"$U_{oc}=1$ V，$R_{eq}=1$ Ω","s":"开关打开时 $I=(10-2.5)/5=1.5$ A，$u_{ab}=U_{oc}+R_{eq}\\times1.5=2.5$；开关闭合时 $I=10/5=2$ A，$i_N=2-3=-1$ A，$0=U_{oc}+R_{eq}\\times(-1)$；联立得 $U_{oc}=1$ V，$R_{eq}=1$ Ω。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-19","seq":19,"part":"电路","qt":"解答","pts":10,"ch":"ec-analyze","q":"如题19图所示正弦稳态电路，已知 $I_s=2\\angle0°$ A，负载 $Z_L$ 可变。为使 $Z_L$ 获得最大功率，求此时 $Z_L$ 及其吸收的最大功率 $P_{\\max}$。[题19图：25 Ω、0.5 Ω、-j25 Ω、受控源与负载 $Z_L$]","img":"pro-img/final-ec_p18.jpg","a":"$Z_L=(10+j)$ Ω；$P_{\\max}=43.33$ W","s":"由 KCL/受控源关系与 KVL 求得戴维南等效 $Z_0=10-j$ Ω 及开路电压 $U_{oc}$；令 $Z_L=Z_0^*=10+j$ Ω 时获最大功率，$P_{\\max}=\\frac{|U_{oc}|^2}{4R_0}=43.33$ W。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc16-20","seq":20,"part":"电路","qt":"解答","pts":10,"ch":"ec-resonance","q":"如题20图所示正弦稳态电路，已知 $U_s=10\\sqrt2\\angle0°$ V。求：(1) 当电源角频率 $\\omega=20$ rad/s 时，电流的有效值 $I$ 为多少？(2) 当电源角频率 $\\omega$ 为多少时，电流的有效值 $I$ 为零？(3) 当电源角频率 $\\omega$ 为多少时，电流的有效值 $I$ 最大，并求其最大值。[题20图：0.3 F、0.1 H、0.1 F 构成的电路]","img":"pro-img/final-ec_p18.jpg","a":"(1) $I=12$ A；(2) $\\omega=10$ rad/s；(3) $\\omega=5$ rad/s，$I_{\\max}$ 原文不清","s":"(1) $\\omega=20$ 时 $0.3F\\to-j/6$ Ω，$0.1H\\to j2$ Ω，$0.1F\\to-j/2$ Ω，等效阻抗 $Z=-j\\dfrac{5}{6}$ Ω，$I=\\dfrac{10}{5/6}=12$ A；(2) $I=0$ 时 $L$ 与 $0.1F$ 并联谐振，$\\omega=\\dfrac{1}{\\sqrt{0.1\\times0.1}}=10$ rad/s；(3) $I$ 最大时全电路串联谐振，$\\omega=\\dfrac{1}{\\sqrt{0.1\\times(0.3+0.1)}}=5$ rad/s。","t":"期末","y":2016,"src":"西电电路2016期末"},{"id":"fc17-01","seq":1,"part":"电路","qt":"选择","pts":3,"ch":"ec-basic","q":"题1图所示电路，$U_s$ 为独立电压源，若外电路不变化，仅 $R$ 发生改变，将会引起（ ）。[题1图：独立电压源 $U_s$ 与电阻 $R$ 的电路]","o":["A. 端电压 $U$ 变化","B. 输出电流 $I$ 变化","C. 电阻 $R$ 支路的电流变化","D. 以上三者同时变化"],"img":"pro-img/final-ec_p07.jpg","a":"C","s":"$U_s$ 与外电路不变，端电压与输出电流 $I$ 均不变；$R$ 变化，则 $R$ 支路电流 $I_R=\\dfrac{U_s}{R}$ 变化。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-02","seq":2,"part":"电路","qt":"选择","pts":3,"ch":"ec-sinusoidal","q":"耦合线圈的自感 $L_1=2$ H，$L_2=8$ H，则互感 $M$ 至多能为（ ）。","o":["A. 8 H","B. 16 H","C. 4 H","D. 6 H"],"img":"pro-img/final-ec_p07.jpg","a":"C","s":"$M=k\\sqrt{L_1L_2}$（$k$ 为耦合系数，$k\\le1$），仅当 $k=1$ 时有最大互感 $M=\\sqrt{L_1L_2}=\\sqrt{2\\times8}=4$ H。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-03","seq":3,"part":"电路","qt":"选择","pts":3,"ch":"ec-basic","q":"题3图所示电路，其中电压源的发出功率是（ ）。[题3图：含 8 V 电压源、6 Ω 与 3 Ω 电阻、1.5 A 电流源的电路]","o":["A. $-4$ W","B. 4 W","C. $-20$ W","D. 20 W"],"img":"pro-img/final-ec_p07.jpg","a":"A","s":"等效变换得 $I_2=1$ A，$I+1.5=I_2$，故 $I=-0.5$ A；$P=U_sI=8\\times(-0.5)=-4$ W。电压电流为关联参考方向时 $P<0$ 表示发出，故发出功率为 $-4$ W。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-04","seq":4,"part":"电路","qt":"选择","pts":3,"ch":"ec-basic","q":"题4图所示电路，其中电流 $I$ 的值是（ ）。[题4图：含 4 A 电流源、2 V 电压源与两个 1 Ω 电阻的电路]","o":["A. 1 A","B. $-2$ A","C. 3 A","D. $-4$ A"],"img":"pro-img/final-ec_p07.jpg","a":"C","s":"$(4-I)\\times1+2=I\\times1$，得 $I=3$ A。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-05","seq":5,"part":"电路","qt":"选择","pts":3,"ch":"ec-analyze","q":"题5图为线性电路，调节可变电阻 $R$ 两次。第一次测得电流表读数为 2 A，电压表读数为 20 V；第二次测得电流表读数为 4 A，电压表读数为 10 V。则含源电路 $N_s$ 的戴维南等效电路中的开路电压 $U_{oc}$ 和戴维南等效内阻 $R_o$ 分别为（ ）。[题5图：含源电路 $N_s$、可变电阻 $R$ 及电流表、电压表]","o":["A. $U_{oc}=10$ V，$R_o=10$ Ω","B. $U_{oc}=30$ V，$R_o=5$ Ω","C. $U_{oc}=20$ V，$R_o=2.5$ Ω","D. $U_{oc}=15$ V，$R_o=8$ Ω"],"img":"pro-img/final-ec_p07.jpg","a":"B","s":"对 $N_s$ 做戴维南等效，有 $U_{oc}=IR_o+U$。由 $\\begin{cases}U_{oc}=2R_o+20\\\\U_{oc}=4R_o+10\\end{cases}$ 解得 $U_{oc}=30$ V，$R_o=5$ Ω。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-06","seq":6,"part":"电路","qt":"选择","pts":3,"ch":"ec-dynamic","q":"题6图所示电路，已知 S 闭合前电路处于稳态，当 $t=0$ 时，开关 S 闭合，则当 $t=0_+$ 时，电流 $i(0_+)$ 的值为（ ）。[题6图：含 10 V 电压源、6 Ω、4 Ω、2 Ω 电阻、电容、电感与开关 S 的电路]","o":["A. 4 A","B. 1 A","C. 3 A","D. 6 A"],"img":"pro-img/final-ec_p08.jpg","a":"C","s":"换路定理：$u_c(0_-)=u_c(0_+)=\\dfrac{10}{6+4}\\times4=4$ V，$i(0_-)=i(0_+)=\\dfrac{10}{6+4}=1$ A；$t=0_+$ 开关闭合瞬间 6 Ω 被短路，故 $i(0_+)=\\dfrac{10-4}{2}=3$ A。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-07","seq":7,"part":"电路","qt":"选择","pts":3,"ch":"ec-sinusoidal","q":"题7图所示正弦稳态电路中，电流表 A、$A_1$、$A_2$ 的读数均为有效值，若 A 的读数为 10 A，$A_1$ 的读数为 8 A，则 $A_2$ 的读数是（ ）。[题7图：正弦稳态电路，含电流表 A、A1、A2]","o":["A. 2 A","B. 3 A","C. 4 A","D. 6 A"],"img":"pro-img/final-ec_p08.jpg","a":"D","s":"画相量图，得 $I_2=\\sqrt{I^2-I_1^2}=\\sqrt{10^2-8^2}=6$ A。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-08","seq":8,"part":"电路","qt":"选择","pts":3,"ch":"ec-sinusoidal","q":"题8图电路中，$R_1=5$ Ω，$R_2=125$ Ω，若要负载 $R_2$ 获得最大功率，那么变压器的变比 $n$ 应该为（ ）。[题8图：变压器 $n:1$，初级接 $R_1$，次级接负载 $R_2$]","o":["A. $\\dfrac{1}{25}$","B. $\\dfrac{1}{5}$","C. 5","D. 25"],"img":"pro-img/final-ec_p08.jpg","a":"B","s":"要获得最大功率，则次级折合至初级的阻抗 $Z=n^2R_2$ 应等于 $R_1$，即 $n^2R_2=R_1$，得 $n=\\sqrt{\\dfrac{R_1}{R_2}}=\\sqrt{\\dfrac{5}{125}}=\\dfrac{1}{5}$。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-09","seq":9,"part":"电路","qt":"选择","pts":3,"ch":"ec-resonance","q":"题9图电路中，发生了串联谐振，已知谐振时电流有效值为 $I=5$ A，电压有效值为 $U_L=200$ V，该谐振电路的品质因数 $Q$ 是（ ）。[题9图：串联谐振电路，含电阻与电感（电压 $U_L$）]","o":["A. 5","B. 15","C. 20","D. 40"],"img":"pro-img/final-ec_p09.jpg","a":"C","s":"串联谐振时 $U_L=QU_s$，而 $U_s=IR=5\\times2=10$ V，故 $Q=\\dfrac{U_L}{U_s}=\\dfrac{200}{10}=20$。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-10","seq":10,"part":"电路","qt":"选择","pts":3,"ch":"ec-sinusoidal","q":"题10图所示电路，$u(t)=100\\cos100t$ V，若负载（感性）的平均功率和无功功率分别是 6 W 和 8 Var，如果要求电源的功率因数为 1，应并联的电容 $C$ 为（ ）。[题10图：电压源 $u(t)$、感性负载与并联电容 $C$ 的电路]","o":["A. $6\\ \\mu$F","B. $8\\ \\mu$F","C. $12\\ \\mu$F","D. $16\\ \\mu$F"],"img":"pro-img/final-ec_p09.jpg","a":"D","s":"$\\cos\\varphi=1$ ⇒ 电路并联后为纯阻性，无功功率应为 0，即 $Q_C+Q_L=0$，$Q_C=-8$ Var；$U=50\\sqrt2\\angle0°$ V，$Q_C=-\\dfrac{U^2}{X_C}=-U^2\\omega C$，故 $C=\\dfrac{8}{(50\\sqrt2)^2\\times100}=16\\ \\mu$F。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-11","seq":11,"part":"电路","qt":"填空","pts":4,"ch":"ec-basic","q":"题11图所示电路，当 $I=0$ 时，电阻 $R=$ ____ Ω。[题11图：含 3 Ω 电阻、9 V 电压源与电阻 $R$ 的电路]","img":"pro-img/final-ec_p09.jpg","a":"$R=6$ Ω","s":"由题意列 KVL 方程得 $I=1$ A，$9=3I+IR$，解得 $R=6$ Ω。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-12","seq":12,"part":"电路","qt":"填空","pts":4,"ch":"ec-dynamic","q":"直流激励下的一阶动态电路中，已知电容电压 $u_c(t)=8+6e^{-5t}$ V，$t\\ge0$，则电容电压的零输入响应为 ____ V；零状态响应为 ____ V。","img":"pro-img/final-ec_p09.jpg","a":"零输入响应 $14e^{-5t}$ V；零状态响应 $8(1-e^{-5t})$ V","s":"$u_c(0_+)=8+6=14$ V，$u_c(\\infty)=8$ V，$\\tau=0.2$ s；零输入响应 $u_{zi}=u_c(0_+)e^{-t/\\tau}=14e^{-5t}$ V；零状态响应 $u_{zs}=u_c(\\infty)(1-e^{-t/\\tau})=8(1-e^{-5t})$ V。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-13","seq":13,"part":"电路","qt":"填空","pts":4,"ch":"ec-analyze","q":"题13图所示单口网络，该网络 ab 端的戴维南等效电路中，开路电压 $U_{oc}=$ ____ V，戴维南等效内阻 $R_o=$ ____ Ω。[题13图：含 10 V 电压源、5 Ω 电阻与受控电压源 $2i$ 的单口网络]","img":"pro-img/final-ec_p09.jpg","a":"$U_{oc}=4$ V；$R_o=0$ Ω","s":"开路时 $i=\\dfrac{10}{5}=2$ A，故 $u=2i=4$ V；受控源为恒压源（$i=2$ A 为定值），短路电流相当于短路恒压源，故等效内阻 $R_o=0$ Ω。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-14","seq":14,"part":"电路","qt":"填空","pts":4,"ch":"ec-sinusoidal","q":"题14图所示耦合线圈，其端口等效电感 $L_{ab}=$ ____ H。[题14图：耦合线圈，端口 a、b，互感 $M=3$ H]","img":"pro-img/final-ec_p09.jpg","a":"$L_{ab}=4$ H","s":"答案页：$L_{ab}=4$ H（两线圈反接串联，$L_{ab}=L_1+L_2-2M$）。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-15","seq":15,"part":"电路","qt":"填空","pts":4,"ch":"ec-twoport","q":"题15图所示二端口电路，其 Z 参数矩阵 $Z=$ ____。[题15图：二端口电路，含 2 Ω、4 Ω 电阻与受控源]","img":"pro-img/final-ec_p10.jpg","a":"$Z=\\begin{bmatrix}6&8\\\\4&8\\end{bmatrix}$ Ω","s":"$U_1=6I_1+8I_2$，$U_2=4I_1+8I_2$，故 $Z=\\begin{bmatrix}6&8\\\\4&8\\end{bmatrix}$ Ω。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-16","seq":16,"part":"电路","qt":"解答","pts":10,"ch":"ec-analyze","q":"题16图所示电路，求图中电压 $U$ 的值。[题16图：含 1 A、2 A 电流源、3 V 电压源及 2 Ω、3 Ω、4 Ω、5 Ω 电阻的电路]","img":"pro-img/final-ec_p10.jpg","a":"$U=2.5$ V","s":"电源等效变换：将 1 A 电流源串联的 4 Ω 电阻省略；左端 1 A 电流源并联 2 Ω 等效为 2 V 电压源串联 2 Ω；右端 3 V 电压源串联 3 Ω 等效为 1 A 电流源并联 3 Ω，再与 2 A 电流源合并为 1 A 电流源（向下）并联 3 Ω，进而等效为 3 V 电压源（上负下正）串联 3 Ω。由等效电路 $(2+5+3)I=2+3$ 得 $I=0.5$ A，$U=5I=2.5$ V。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-17","seq":17,"part":"电路","qt":"解答","pts":10,"ch":"ec-dynamic","q":"题17图电路中，$t<0$ 时电路处于稳态，$t=0$ 时开关 S 由位置 1 打到位置 2，求 $t\\ge0$ 后的 $u_o(t)$。[题17图：含 3 A 电流源、2 Ω 电阻、1 F 电容与开关 S 的电路]","img":"pro-img/final-ec_p11.jpg","a":"$u_o(t)=6-6e^{-t/4}$ V（$t\\ge0$）","s":"$u_o(0_+)=u_o(0_-)=0$ V；达稳态时用伏安关系法做戴维南等效，得 $u=4I+6$，故 $R_o=4$ Ω，$U_{oc}=6$ V，即 $u_o(\\infty)=6$ V，$\\tau=R_oC=4\\times1=4$ s；$u_o(t)=[u_o(0_+)-u_o(\\infty)]e^{-t/\\tau}+u_o(\\infty)=-6e^{-t/4}+6$ V。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-18","seq":18,"part":"电路","qt":"解答","pts":10,"ch":"ec-resonance","q":"题18图电路中，正弦电压 $u(t)$ 的有效值 $U=200$ V，电流表 $A_2$ 的读数为零，求电流表 $A_1$ 的读数是多少？[题18图：正弦稳态电路，含 50 Ω、0.2 H、5 μF、0.1 H、10 μF 元件及电流表 A1、A2]","img":"pro-img/final-ec_p11.jpg","a":"$I_1=\\sqrt{17}$ A","s":"$A_2$ 读数为零 ⇒ 10 μF 与 0.1 H 发生并联谐振（开路），$\\omega=\\dfrac{1}{\\sqrt{0.1\\times10\\times10^{-6}}}=10^3$ rad/s；又 $\\dfrac{1}{\\sqrt{0.2\\times5\\times10^{-6}}}=10^3$ rad/s，$A_1$ 左边电路发生串联谐振，总电流 $I=\\dfrac{200}{50+50}=2$ A（$2\\angle0°$ A）；以 $U=200\\angle0°$ V 为相量，0.1 H 电感两端电压为 $(100+j400)$ V，其电流 $=\\dfrac{100+j400}{j100}=(1+j4)$ A，故 $A_1$ 读数 $I_1=\\sqrt{4^2+1}=\\sqrt{17}$ A。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-19","seq":19,"part":"电路","qt":"解答","pts":10,"ch":"ec-sinusoidal","q":"题19图所示电路中，电压源的有效值 $U=200$ V，负载 $Z_L$ 可变，求当 $Z_L$ 为多大时，其上能获最大功率，该最大功率是多少？[题19图：含变压器 10:1、两个 $-j2$ Ω 电容、两个 1 Ω 电阻与可变负载 $Z_L$ 的电路]","img":"pro-img/final-ec_p12.jpg","a":"$Z_L=1$ Ω，最大功率 $100$ W","s":"设 $U=200\\angle0°$ V。求开路电压 $U_{oc}=20\\angle-90°$ V，等效内阻 $Z_0=1$ Ω（或将次级阻抗折合至初级：$Z_{eq}=[100\\parallel j100]+[100\\parallel(-j100)]=100$ Ω）。当且仅当 $Z_L=Z_0^*=1$ Ω 时获最大功率，$P_{max}=\\dfrac{U_{oc}^2}{4R}=\\dfrac{20^2}{4\\times1}=100$ W。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc17-20","seq":20,"part":"电路","qt":"解答","pts":10,"ch":"ec-analyze","q":"题20图所示电路，N 为无源二端口线性电阻电路。当 $I_1=2$ A，$I_2=0$ 时，$I_1$ 的发出功率为 28 W，且 $U_2=8$ V；当 $I_1=0$，$I_2=3$ A 时，$I_2$ 的发出功率为 54 W，且 $U_1=12$ V。求当 $I_1=2$ A，$I_2=3$ A 共同作用时，两个电源的发出功率各是多少？[题20图：无源二端口线性电阻电路 N 与两个电流源]","img":"pro-img/final-ec_p12.jpg","a":"$I_1$ 发出功率 $52$ W；$I_2$ 发出功率 $78$ W","s":"① $I_1=2$ A、$I_2=0$ 时 $U_2=8$ V，由 $P_1=U_1I_1=28$ W 得 $U_1=14$ V；② $I_1=0$、$I_2=3$ A 时 $U_1=12$ V，由 $P_2=U_2I_2=54$ W 得 $U_2=18$ V。由齐次叠加定理 $U_1=mI_1+nI_2$：$14=2m$、$12=3n$，得 $m=7$、$n=4$，故 $U_1=7I_1+4I_2$；当 $I_1=2$、$I_2=3$ 时 $U_1=7\\times2+4\\times3=26$ V，$P_1=U_1I_1=26\\times2=52$ W。同理 $U_2=pI_1+qI_2$：$8=2p$、$18=3q$，得 $p=4$、$q=6$，故 $U_2=4I_1+6I_2=4\\times2+6\\times3=26$ V，$P_2=U_2I_2=26\\times3=78$ W。","t":"期末","y":2017,"src":"西电电路2017期末"},{"id":"fc19-01","seq":1,"part":"电路","qt":"解答","pts":0,"ch":"ec-sinusoidal","q":"已知电路的相量图模型如图所示，$U_s=200\\angle0°$ V，$I=10\\angle36.9°$ A，$I_L=-10\\angle53.1°$ A，$U_c=-141\\angle-45°$ V。求 $I_1$、$I_2$、$I_3$（$\\arctan0.5\\approx26.6°$，$\\sqrt2\\approx1.41$，$\\sqrt5\\approx2.24$）。[题1图：相量电路模型，含电压源 $U_s$、10 Ω 与 8 Ω 电阻、电感（电流 $I_L$）与电容（电压 $U_c$）]","img":"pro-img/final-ec_p05.jpg","a":"","s":"","t":"期末","y":2019,"src":"西电电路2019期末"},{"id":"fc19-02","seq":2,"part":"电路","qt":"解答","pts":0,"ch":"ec-sinusoidal","q":"电路如图所示，$X_{L1}=2$ Ω，$X_{L2}=8$ Ω，$X_M=4$ Ω，$X_{L3}=4$ Ω，$R_1=6$ Ω，$R_2=12$ Ω，$U=120$ V。求 $i_1$、$i_2$。[题2图：耦合电感电路，含 $jX_{L1}$、$jX_M$、$L_2$、$L_3$ 及电阻 $R_1$、$R_2$，端口 a-b]","img":"pro-img/final-ec_p06.jpg","a":"","s":"","t":"期末","y":2019,"src":"西电电路2019期末"},{"id":"fc19-03","seq":3,"part":"电路","qt":"解答","pts":0,"ch":"ec-resonance","q":"如图所示的滤波器能够阻止信号的基波通至负载 $R_L$，同时能够使十次谐波顺利地通至负载，设 $C=0.01$ μF，基波角频率 $\\omega=10^5$ rad/s，求电感 $L_1$ 和 $L_2$。[题3图：滤波器电路，含电感 $L_1$、$L_2$、电容 $C$ 与负载 $R_L$]","img":"pro-img/final-ec_p06.jpg","a":"$L_1=0.01$ H（$10$ mH）；$L_2=101$ μH","s":"基波不能通过 ⇒ $L_1$ 与 $C$ 并联电路对基波发生并联谐振（谐振阻抗无穷大，断路），$L_1=\\dfrac{1}{\\omega^2C}=0.01$ H；十次谐波顺利通过 ⇒ $L_1\\parallel C$ 再与 $L_2$ 串联的组合对十次谐波发生串联谐振（谐振阻抗为零，短路），$j10\\omega L_2+\\dfrac{1}{j10\\omega C-\\dfrac{j}{10\\omega L_1}}=0$，代入 $L_1=0.01$ H、$\\omega=10^5$ rad/s、$C=0.01$ μF 得 $L_2=101$ μH。评注：课本例 5.4-3 原题。","t":"期末","y":2019,"src":"西电电路2019期末"},{"id":"fc21-01","seq":1,"part":"电路","qt":"填空","pts":5,"ch":"ec-basic","q":"电路如题1图所示，网络 N 发出的功率为 ____。[题1图：10 V 电压源、5 Ω 电阻与网络 N]","img":"pro-img/final-ec_p01.jpg","a":"-10 W","s":"","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-02","seq":2,"part":"电路","qt":"填空","pts":5,"ch":"ec-dynamic","q":"某电容 $C=6$ F，其上电压与电流取非关联参考方向，已知电压 $u(t)=1-e^{-t}$ V（$t\\ge0$），则 $t\\ge0$ 时的电容电流 $i(t)$ 为 ____。","img":"pro-img/final-ec_p01.jpg","a":"-6e^{-t} A","s":"","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-03","seq":3,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"在题3图所示的正弦稳态电路中，为了使 $\\dot U_1$ 超前 $\\dot U_2$，则阻抗 $Z$ 应呈 ____（电阻/电容/电感）性。[题3图：正弦稳态电路，含阻抗 Z，具体连接见图]","img":"pro-img/final-ec_p01.jpg","a":"","s":"","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-04","seq":4,"part":"电路","qt":"填空","pts":5,"ch":"ec-dynamic","q":"如题4图，RL 串联电路与电压为 8 V 的电压源接通，如图(a)所示。在 $t=0$ 瞬间将开关 S 闭合，当电感分别为 1 H、2 H、3 H、4 H 时所得到的 4 条曲线如图(b)。其中 3 H 电感所对应的曲线是 ____。[题4图(a)：RL 串联电路接 8 V 电压源与开关 S；(b)：4 条电流曲线]","img":"pro-img/final-ec_p01.jpg","a":"","s":"","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-05","seq":5,"part":"电路","qt":"填空","pts":5,"ch":"ec-resonance","q":"如题5图所示的并联谐振电路，其中 $r$ 为电感线圈的损耗内阻。已知该谐振电路的品质因数 $Q$ 较高，谐振时谐振电阻表达式为 ____。[题5图：并联谐振电路，电感线圈含损耗内阻 r]","img":"pro-img/final-ec_p01.jpg","a":"$R_0=\\dfrac{L}{rC}$","s":"","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-06","seq":6,"part":"电路","qt":"填空","pts":5,"ch":"ec-twoport","q":"如题6图所示二端口网络的 Y 参数矩阵为 ____。[题6图：二端口网络，具体元件见图]","img":"pro-img/final-ec_p01.jpg","a":"","s":"","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-07","seq":7,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"电路如题7图，已知 $u(t)=9e^{-t}$ V，$i(t)=6\\cos 2t$ A，求 ____(t)。[题7图：含 2 H、1 H、3 H、5 H 电感，4 Ω 电阻，电压源 u(t) 与电流源 i(t)]","img":"pro-img/final-ec_p02.jpg","a":"","s":"","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-08","seq":8,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"计算题8图中 ab 端口间的等效电感 ____。[题8图：电感网络（ab 端口），具体连接见图]","img":"pro-img/final-ec_p02.jpg","a":"","s":"","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-09","seq":9,"part":"电路","qt":"解答","pts":10,"ch":"ec-analyze","q":"电路如题9图，参考节点如图所示，确定节点电压 $U_3$。[题9图：含 7 V 电压源、1.5 A 与 1 A 电流源、1 Ω 与 2 Ω 电阻，节点电压 U1、U2、U3]","img":"pro-img/final-ec_p02.jpg","a":"$U_3=2$ V","s":"列节点电压方程：$4U_1-2U_2-U_3=-4$，$-2U_1+3U_2-U_3=5$，$-U_1-U_2+4U_3=4$；解得 $U_1=1$ V，$U_2=3$ V，$U_3=2$ V。","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-10","seq":10,"part":"电路","qt":"解答","pts":7,"ch":"ec-analyze","q":"求题10图中电路 ab 端的等效电阻。[题10图：含 1 Ω、2 Ω 电阻与受控源 2U]","img":"pro-img/final-ec_p02.jpg","a":"$R_{eq}=-1$ Ω","s":"ab 端外接恒流源 $I$（方向向上），则 $U=I$；根据 KCL，2 Ω 上电流为 $I$（方向向上）。故 $U_{ab}=I-2I=-I$，戴维南等效电阻 $R_{eq}=\\dfrac{U_{ab}}{I}=-1$ Ω。","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-11","seq":11,"part":"电路","qt":"解答","pts":10,"ch":"ec-dynamic","q":"如题11图所示电路，$U_s=5$ V，$I_s=2$ A，$R_1=1$ Ω，$R_2=R_3=2$ Ω，$C=1$ F。在 $t<0$ 时开关位于「1」，电路已处于稳态；$t=0$ 时开关 S 由「1」闭合到「2」，经过 4 s 后，开关 S 又由「2」闭合到「3」。求 $t\\ge0$ 时电容上的电流。（不用算出 e 的幂次的具体数值）[题11图：三位置开关 S、电容 C、电阻 R1、R2、R3，电压源 Us、电流源 Is]","img":"pro-img/final-ec_p03.jpg","a":"","s":"","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-12","seq":12,"part":"电路","qt":"解答","pts":10,"ch":"ec-sinusoidal","q":"正弦稳态电路如题12图所示。若负载既有电阻又有动态元件，求在负载获得最大功率时负载元件参数值，并求负载获得的最大功率。[题12图：含 1 H 电感、1 Ω 电阻、2 F 电容、电流源 $\\cos(t)$ A 与电压源 $\\cos(t)$ V]","img":"pro-img/final-ec_p03.jpg","a":"","s":"","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-13","seq":13,"part":"电路","qt":"解答","pts":10,"ch":"ec-resonance","q":"如题13图所示并联谐振电路。(1) 已知 $r=100$ kΩ，$L=200$ μH，带宽 $B=5\\times10^4$ rad/s，求电容 $C$、谐振角频率 $\\omega_0$ 及电路的品质因数 $Q$；(2) 为使(1)中的带宽拓展为 $B=10^7$ rad/s，需在回路两端并联一个电阻 $R$，求此电阻 $R$ 的值。[题13图：并联谐振电路]","img":"pro-img/final-ec_p04.jpg","a":"(1) $C=200$ pF，$\\omega_0=5\\times10^6$ rad/s，$Q=100$；(2) $R\\approx502.5$ Ω","s":"(1) $C=\\dfrac{1}{Br}=\\dfrac{1}{5\\times10^4\\times10^5}=2\\times10^{-10}$ F $=200$ pF；$\\omega_0=\\dfrac{1}{\\sqrt{LC}}=\\dfrac{1}{\\sqrt{2\\times10^{-4}\\times2\\times10^{-10}}}=5\\times10^6$ rad/s；$Q=\\dfrac{\\omega_0}{B}=\\dfrac{5\\times10^6}{5\\times10^4}=100$。(2) 并联后总电阻 $r'=\\dfrac{1}{B'C}=\\dfrac{1}{10^7\\times2\\times10^{-10}}=500$ Ω，故 $R=\\dfrac{rr'}{r-r'}=\\dfrac{10^5\\times500}{10^5-500}\\approx502.5$ Ω。","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"fc21-14","seq":14,"part":"电路","qt":"解答","pts":10,"ch":"ec-analyze","q":"电路如题14图所示，N 为不含独立源的线性电阻网络，已知输出电压 $U=0.5U_s$。若输出端接上 5 Ω 的电阻，则 $U=0.1U_s$。问在输出端接上 10 Ω 的电阻时，输出电压 $U$ 与激励 $U_s$ 的关系是什么？[题14图：线性电阻网络 N 与激励 $u_s$]","img":"pro-img/final-ec_p04.jpg","a":"$U=\\dfrac{1}{6}U_s$","s":"对电路进行戴维南等效，设开路电压为 $U_{oc}$、等效电阻为 $R_{eq}$。输出端开路时 $U=U_{oc}=0.5U_s$；接入 5 Ω 电阻时 $U=\\dfrac{5}{R_{eq}+5}U_{oc}=0.1U_s$，解得 $R_{eq}=20$ Ω；接入 10 Ω 电阻时 $U=\\dfrac{10}{10+20}U_{oc}=\\dfrac{1}{3}\\times0.5U_s=\\dfrac{1}{6}U_s$。","t":"期末","y":2021,"src":"西电电路2021期末"},{"id":"r24-13","seq":13,"part":"电路","qt":"解答","pts":5,"ch":"ec-basic","q":"如图1所示电路，试求 $1\\Omega$ 电阻吸收的功率。[图1：含 10A 电流源、$10\\Omega$、$17\\Omega$、$1\\Omega$ 电阻与受控源 $0.5i$ 的电路]","img":"pro-img/2024_p04.jpg","a":"25 W","s":"由 KVL 及 KCL 列方程（答案页公式原文不清），解得 $i=5$ A，故 $P=i^2R=5^2\\times1=25$ W。","t":"真题","y":2024,"src":"西电8112024真题"},{"id":"r24-14","seq":14,"part":"电路","qt":"解答","pts":5,"ch":"ec-sinusoidal","q":"如图2所示电路，电流表 $A_1,A_2,A_3$ 的读数分别为 5A、20A、25A，试求电流表 $A$ 的读数。[图2：三支路正弦电流叠加]","img":"pro-img/2024_p05.jpg","a":"$5\\sqrt2$ A","s":"设 $i_1=5\\angle0^\\circ$ A，则 $i_2=20\\angle-90^\\circ$ A，$i_3=25\\angle90^\\circ$ A，$i=i_1+i_2+i_3=5+j5=5\\sqrt2\\angle45^\\circ$ A，故读数 $I=5\\sqrt2$ A。","t":"真题","y":2024,"src":"西电8112024真题"},{"id":"r24-15","seq":15,"part":"电路","qt":"解答","pts":5,"ch":"ec-analyze","q":"如图3所示电路，试求可变电阻 $R$ 能够获得的最大功率。[图3：含 5Ω、3Ω、6V 电压源与受控源的电路]","img":"pro-img/2024_p05.jpg","a":"$\\dfrac{49}{10}$ W（4.9 W）","s":"外加电源求端口伏安关系，由 KVL 及 KCL 得 $u=10i+14$，故戴维南等效 $R_o=10\\ \\Omega$，$U_{oc}=14$ V，$P_{max}=\\dfrac{U_{oc}^2}{4R_o}=\\dfrac{14^2}{4\\times10}=\\dfrac{49}{10}$ W。","t":"真题","y":2024,"src":"西电8112024真题"},{"id":"r24-16","seq":16,"part":"电路","qt":"解答","pts":5,"ch":"ec-twoport","q":"如图4所示二端口网络电路，已知 $L_1=4$ H，$L_2=6$ H，$M=3$ H，$\\omega=100$ rad/s，求其 z 参数矩阵。[图4：耦合电感二端口]","img":"pro-img/2024_p05.jpg","a":"$Z=\\begin{bmatrix}j400&j300\\\\j300&j600\\end{bmatrix}\\ \\Omega$","s":"$U_1=j\\omega L_1 i_1+j\\omega M i_2=j400i_1+j300i_2$；$U_2=j\\omega M i_1+j\\omega L_2 i_2=j300i_1+j600i_2$。","t":"真题","y":2024,"src":"西电8112024真题"},{"id":"r24-17","seq":17,"part":"电路","qt":"解答","pts":5,"ch":"ec-analyze","q":"如图5所示电路，求电位 $U_A$。[图5：含 24V、16V、6V 电压源与 9Ω、3Ω 电阻的电路]","img":"pro-img/2024_p06.jpg","a":"$-35.5$ V","s":"由 KVL 及分压关系 $U_A=-24+\\dfrac{3}{9+3}\\times(24-6)-16=-35.5$ V（答案页分压系数原文不清，据结果恢复为 $\\tfrac3{9+3}$）。","t":"真题","y":2024,"src":"西电8112024真题"},{"id":"r24-18","seq":18,"part":"电路","qt":"解答","pts":5,"ch":"ec-dynamic","q":"如图6所示电路，$t<0$ 时电路已达稳态，$t=0$ 时开关闭合，试求初始值 $i(0_+)$。[图6：含 1F 电容、电感与电阻的电路]","img":"pro-img/2024_p06.jpg","a":"$-1$ A","s":"由 $0_-$ 时刻电路和换路定理得 $i_L(0_+)=i_L(0_-)=1$ A，$u_C(0_+)=u_C(0_-)=4$ V；$0_+$ 时刻电路列 KCL：$1=1+1+i(0_+)$，解得 $i(0_+)=-1$ A。","t":"真题","y":2024,"src":"西电8112024真题"},{"id":"r24-19","seq":19,"part":"电路","qt":"解答","pts":5,"ch":"ec-sinusoidal","q":"如图7所示电路，已知 $i_s(t)=2\\cos t$ A，求 $u_o(t)$。[图7：0.5H 电感、1F 电容与两个 1Ω 电阻的正弦稳态电路]","img":"pro-img/2024_p06.jpg","a":"$u_o(t)=2\\sqrt2\\cos(t-45^\\circ)$ V（系数据答案页）","s":"相量模型（$\\omega=1$ rad/s）：电感 $j0.5\\ \\Omega$、电容 $-j1\\ \\Omega$。由答案页得 $U_o=\\dfrac{1\\parallel(-j1)}{1\\parallel(-j1)+1+j0.5}\\cdot(2\\sqrt2\\angle0^\\circ)=2\\sqrt2\\angle-45^\\circ$ V（解析公式原文不清），故 $u_o(t)=2\\sqrt2\\cos(t-45^\\circ)$ V。","t":"真题","y":2024,"src":"西电8112024真题"},{"id":"r24-20","seq":20,"part":"电路","qt":"解答","pts":5,"ch":"ec-resonance","q":"如图8所示电路，其中 $r=10\\ \\Omega$，$C=4\\ \\mu$F，当 $\\omega_0=250$ rad/s 时电阻 $r$ 的电压达到最大值，试求电感 $L$。[图8：RLC 谐振电路]","img":"pro-img/2024_p06.jpg","a":"4 H","s":"电阻 $r$ 电压最大即发生串联谐振，$\\omega_0=\\dfrac1{\\sqrt{LC}}$，故 $L=\\dfrac1{\\omega_0^2C}=\\dfrac1{250^2\\times4\\times10^{-6}}=4$ H。","t":"真题","y":2024,"src":"西电8112024真题"},{"id":"r24-21","seq":21,"part":"电路","qt":"解答","pts":6,"ch":"ec-analyze","q":"如图9所示电路，请用节点法计算响应 $u_x$ 和 $i$。[图9：含 4Ω、2Ω 电阻、2V 电压源与受控源 $2u_x$ 的电路]","img":"pro-img/2024_p07.jpg","a":"$u_x=2$ V，$i=1$ A","s":"取参考节点，设节点电压 $u_{n1},u_{n2},u_{n3}$，$u_{n2}=2$ V（2V 源），解得 $u_{n1}=6$ V，$u_{n3}=4$ V。故 $u_x=u_{n3}-u_{n2}=4-2=2$ V，$i=\\dfrac12\\times(6-4)=1$ A。","t":"真题","y":2024,"src":"西电8112024真题"},{"id":"r24-22","seq":22,"part":"电路","qt":"解答","pts":9,"ch":"ec-dynamic","q":"如图10所示电路，$t<0$ 时电路已处于稳态，$t=0$ 时开关 S 由\"1\"闭合至\"2\"，求：(1) $t\\ge0$ 时，电压 $u_c$ 的零输入响应；(2) $t\\ge0$ 时，电流 $i$ 的零状态响应和全响应。[图10：含 2A 源、2Ω、3Ω、6Ω 电阻与 1F 电容的电路]","img":"pro-img/2024_p07.jpg","a":"(1) $u_{c,zi}(t)=3e^{-t/4}$ V（$t\\ge0$）；(2) $u_c(t)=4-e^{-t/4}$ V，$i(t)=\\dfrac14e^{-t/4}$ A（$t\\ge0$）","s":"由 $0_-$ 电路和换路定理 $u_c(0_+)=u_c(0_-)=\\dfrac{3}{3+2}\\times5=3$ V；稳态 $u_c(\\infty)=2\\times(3\\parallel6)=4$ V；$\\tau=RC=(2+3\\parallel6)\\times1=4$ s。零输入 $u_{c,zi}=3e^{-t/4}$ V；全响应 $u_c=4+(3-4)e^{-t/4}=4-e^{-t/4}$ V；$i=C\\dfrac{du_c}{dt}=\\dfrac14e^{-t/4}$ A。","t":"真题","y":2024,"src":"西电8112024真题"},{"id":"r24-23","seq":23,"part":"电路","qt":"解答","pts":11,"ch":"ec-resonance","q":"如图11所示简单并联谐振电路。(1) 已知 $L=0.1$ mH，$C=400$ pF，$r=5\\ \\Omega$，求谐振频率 $f_0$、谐振阻抗 $Z_0$、品质因数 $Q$ 和带宽 $B$；(2) 已知 $L=0.1$ mH，若要求谐振频率为 $f_0=600$ kHz、品质因数 $Q=20$，试求电容 $C$ 和带宽 $B$；(3) 已知 $L=0.1$ mH，$C=400$ pF，$r=5\\ \\Omega$，若通过在回路右侧并联电阻 $R$ 使 $Q=50$，求并联电阻 $R$ 的值。[图11：并联谐振电路]","img":"pro-img/2024_p07.jpg","a":"(1) $f_0=\\dfrac{10^7}{4\\pi}\\approx7.96\\times10^5$ Hz，$Z_0=\\dfrac{L}{Cr}=5\\times10^4\\ \\Omega$，$Q=100$，$B\\approx7.96\\times10^3$ Hz；(2) $C=\\dfrac1{(2\\pi f_0)^2L}\\approx7.04\\times10^{-10}$ F（约 704 pF），$B=\\dfrac{f_0}{Q}=30$ kHz；(3) $R=5\\times10^4\\ \\Omega$（50 kΩ）","s":"(1) $f_0=\\dfrac1{2\\pi\\sqrt{LC}}=\\dfrac1{2\\pi\\sqrt{0.1\\times10^{-3}\\times400\\times10^{-12}}}=\\dfrac{10^7}{4\\pi}$ Hz；$Z_0=\\dfrac{L}{Cr}=5\\times10^4\\ \\Omega$；$Q=\\dfrac1r\\sqrt{\\dfrac LC}=\\dfrac{500}{5}=100$；$B=\\dfrac{f_0}{Q}\\approx7.96\\times10^3$ Hz。(2) $C=\\dfrac1{(2\\pi f_0)^2L}=\\dfrac1{(2\\pi\\times600\\times10^3)^2\\times0.1\\times10^{-3}}\\approx7.04\\times10^{-10}$ F，$B=\\dfrac{f_0}{Q}=30$ kHz。(3) 并联后 $R_{\\text{总}}=Z_0\\parallel R$，$Q=\\dfrac{R_{\\text{总}}}{\\omega_0L}=50$ 得 $R_{\\text{总}}=2.5\\times10^4\\ \\Omega$，由 $Z_0=5\\times10^4\\ \\Omega$ 解得 $R=5\\times10^4\\ \\Omega$。","t":"真题","y":2024,"src":"西电8112024真题"},{"id":"r24-24","seq":24,"part":"电路","qt":"解答","pts":9,"ch":"ec-sinusoidal","q":"如图12所示正弦稳态电路，已知 $X_{L1}=6\\ \\Omega$，$X_{L2}=4\\ \\Omega$，$X_M=2\\ \\Omega$，$X_C=-4\\ \\Omega$，$R_1=4\\ \\Omega$，$R_2=2\\ \\Omega$，$U=60\\angle0^\\circ$ V，求电流 $i_1$、$i_2$ 和电压 $U_o$。[图12：耦合电感正弦稳态电路]","img":"pro-img/2024_p08.jpg","a":"$i_1=5\\sqrt2\\angle-45^\\circ$ A，$i_2=5\\sqrt2\\angle45^\\circ$ A，$U_o=30-j10$ V","s":"去耦等效后 $Z=4+j4+(j2)\\parallel(j2+2-j4)=6+j6\\ \\Omega$，$i_1=\\dfrac{60\\angle0^\\circ}{6+j6}=5\\sqrt2\\angle-45^\\circ$ A，$i_2=\\dfrac{j2}{j2+j2+2-j4}i_1=5\\sqrt2\\angle45^\\circ$ A，$U_o=(2-j4)i_2=(2-j4)\\times5\\sqrt2\\angle45^\\circ=30-j10$ V。","t":"真题","y":2024,"src":"西电8112024真题"},{"id":"r26-13","seq":13,"part":"电路","qt":"填空","pts":5,"ch":"ec-basic","q":"图2-1所示电路，计算电流源 $i_s$ 产生的功率 $P=\\underline{\\qquad}$。[图2-1：含电流源的电阻电路]","img":"pro-img/2026_p05.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r26-14","seq":14,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"计算图2-2所示电路中的电流 $i_x=\\underline{\\qquad}$。[图2-2：含受控源的电路]","img":"pro-img/2026_p05.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r26-15","seq":15,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"图2-3所示电路，若激励电流频率为50Hz，计算ab两点间等效阻抗。[图2-3：含耦合电感的电路]","img":"pro-img/2026_p06.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r26-16","seq":16,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"图2-4所示电路中N为线性无源网络。已知 $U_s=8$V，$R_L=3\\Omega$ 时，电流 $I=0.5$A；当 $U_s=18$V，$R_L=4\\Omega$ 时，电流 $I=1$A，则当 $U_s=30$V，$R_L=10\\Omega$ 时，计算电流 $I$。[图2-4：含线性无源网络 N 的电路]","img":"pro-img/2026_p06.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r26-17","seq":17,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"图2-5所示电路，计算ab端戴维南等效电路中的电阻大小。[图2-5：含受控源电路]","img":"pro-img/2026_p07.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r26-18","seq":18,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"图2-6所示电路，已知 $I=2$A，计算 $U$。[图2-6：正弦稳态电路（含 $-j50\\Omega$、$10\\Omega$、$j100\\Omega$ 阻抗）]","img":"pro-img/2026_p07.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r26-19","seq":19,"part":"电路","qt":"填空","pts":5,"ch":"ec-resonance","q":"图2-7所示电路，已知 $C_1=1\\mu$F，当 $u(t)$ 角频率 $\\omega=10^6$ rad/s 时，$i(t)$ 的值最大；当 $u(t)$ 角频率 $\\omega=10^7$ rad/s 时，$i(t)$ 的值为0，计算 $C_2$。[图2-7：含电容的电路]","img":"pro-img/2026_p08.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r26-20","seq":20,"part":"电路","qt":"填空","pts":5,"ch":"ec-basic","q":"图2-8所示电路中，已知 $u(t)=100\\cos(10t+20°)V$，$i(t)=0.1\\cos(10^{?}t-10°)A$（$i(t)$ 角频率上标原文不清）。计算 N 吸收的有功功率。[图2-8：含网络 N 的正弦电路]","img":"pro-img/2026_p08.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r26-21","seq":21,"part":"电路","qt":"填空","pts":5,"ch":"ec-twoport","q":"图2-9所示的二端口网络，计算Z参数。[图2-9：二端口网络]","img":"pro-img/2026_p09.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r26-22","seq":22,"part":"电路","qt":"解答","pts":8,"ch":"ec-analyze","q":"图2-10所示电路，应用回路电流法计算 $i_x$ 和 $u_x$。[图2-10：含受控源与电流源的电路]","img":"pro-img/2026_p09.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r26-23","seq":23,"part":"电路","qt":"解答","pts":12,"ch":"ec-dynamic","q":"图2-11所示电路，在 $t<0$ 时开关断开，电路已处于稳态。$t=0$ 时开关S闭合，求 $t\\geq 0$ 时的 $u(t)$。[图2-11：含开关与电感的动态电路]","img":"pro-img/2026_p10.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r26-24","seq":24,"part":"电路","qt":"解答","pts":6,"ch":"ec-resonance","q":"图2-12所示电路，电路谐振时电流表A1和A3的读数均为10A，试计算此时电流表A2的读数。（电流表内阻均忽略不计）[图2-12：谐振电路（含电流表）]","img":"pro-img/2026_p10.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r26-25","seq":25,"part":"电路","qt":"解答","pts":4,"ch":"ec-analyze","q":"图2-13所示电路，N为线性电阻网络。已知：当a，b端开路时，输出电压 $u_o=6$V；当a，b端短路时，输出电压 $u_o=8$V。求a，b端接一可变电阻器R，且其能获得最大功率时，输出电压 $u_o$ 为多少。[图2-13：含线性电阻网络 N 的电路]","img":"pro-img/2026_p11.jpg","a":"","s":"","t":"真题","y":2026,"src":"西电8112026真题"},{"id":"r25-13","seq":13,"part":"电路","qt":"填空","pts":5,"ch":"ec-basic","q":"1. 电路如图1所示，试计算图中 $u$ 的大小。[图1：含 $5$ 个 $10\\,\\Omega$ 电阻、$7\\,\\mathrm{A}$ 电流源与受控电流源 $0.5i$ 的电路（见图）]","img":"pro-img/2025_p03.jpg","a":"$u=-30\\,\\mathrm{V}$","s":"对最外圈列 KVL：$10\\times1.5i+10\\times(i-7)+10i=0$，解得 $i=2\\,\\mathrm{A}$；故 $u=-10\\times1.5i=-15i=-30\\,\\mathrm{V}$。","t":"真题","y":2025,"src":"西电8112025真题"},{"id":"r25-14","seq":14,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"2. 如图2所示，负载 $R$ 可变，试计算负载 $R$ 为多少时可以获得最大的功率。[图2：含受控源 $2i$、$0.5u_1$，$6\\,\\Omega$、$12\\,\\Omega$、$4\\,\\Omega\\times2$ 电阻与 $10\\,\\mathrm{A}$ 电流源的电路（见图）]","img":"pro-img/2025_p04.jpg","a":"$R=R_{eq}=2.4\\,\\Omega$","s":"断开负载 $R$，从端口施加 $1\\,\\mathrm{A}$ 电流源（加流加压法），测得端口电压 $u_{端口}=2.4\\,\\mathrm{V}$，故等效电阻 $R_{eq}=\\dfrac{2.4}{1}=2.4\\,\\Omega$；由最大功率传输定理，当 $R=R_{eq}=2.4\\,\\Omega$ 时获得最大功率。","t":"真题","y":2025,"src":"西电8112025真题"},{"id":"r25-15","seq":15,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"3. 如图3(a)所示的电路中，二端电路 $N$ 的 VCR 特性如图3(b)所示，试计算 $i_1$ 为多少。[图3：含 $3\\,\\Omega\\times2$、$6\\,\\Omega$ 电阻与二端电路 $N$（VCR 特性见图(b)，开路电压 $-6\\,\\mathrm{V}$、等效电阻 $2\\,\\Omega$）的电路（见图）]","img":"pro-img/2025_p04.jpg","a":"$i_1=1\\,\\mathrm{A}$","s":"由图3(b)得 $N$ 的 $U_{oc}=-6\\,\\mathrm{V}$、$R_{eq}=2\\,\\Omega$；回路总电阻 $R_{总}=3\\parallel6+3\\parallel6+R_{eq}=2+2+2=6\\,\\Omega$，由 $N$ 的 $-6\\,\\mathrm{V}$ 源驱动，回路电流 $i_1=\\dfrac{6}{6}=1\\,\\mathrm{A}$；再经 $3\\,\\Omega\\parallel6\\,\\Omega$ 分流得支路电流（$3\\,\\Omega$ 支路 $\\frac23\\,\\mathrm{A}$、$6\\,\\Omega$ 支路 $\\frac13\\,\\mathrm{A}$）。","t":"真题","y":2025,"src":"西电8112025真题"},{"id":"r25-16","seq":16,"part":"电路","qt":"填空","pts":5,"ch":"ec-basic","q":"4. 电路如图4所示，已知电压 $U=9\\,\\mathrm{V}$，二端电路 $N$ 消耗的功率 $P$ 是多少？[图4：含 $18\\,\\mathrm{V}$ 电压源、$12\\,\\Omega$、$6\\,\\Omega$ 电阻与二端电路 $N$（端电压 $9\\,\\mathrm{V}$）的电路（见图）]","img":"pro-img/2025_p04.jpg","a":"$P=4.5\\,\\mathrm{W}$","s":"回路电流 $i=\\dfrac{18-9}{12+6}=0.5\\,\\mathrm{A}$，故 $N$ 消耗功率 $P=U\\cdot i=9\\times0.5=4.5\\,\\mathrm{W}$。","t":"真题","y":2025,"src":"西电8112025真题"},{"id":"r25-17","seq":17,"part":"电路","qt":"填空","pts":5,"ch":"ec-analyze","q":"5. 电路如图5所示，从 $ab$ 端向左看的戴维南等效电阻 $R_{eq}$ 是多少？[图5：含 $8\\,\\Omega\\times4$ 电阻与 $1.5\\,\\mathrm{A}$ 电流源的电路（见图）]","img":"pro-img/2025_p04.jpg","a":"$R_{eq}=8\\,\\Omega$","s":"$R_{eq}=(8+8)\\parallel(8+8)=16\\parallel16=8\\,\\Omega$。","t":"真题","y":2025,"src":"西电8112025真题"},{"id":"r25-18","seq":18,"part":"电路","qt":"填空","pts":5,"ch":"ec-resonance","q":"6. 电路如图6所示，已知 $L=200\\,\\mu\\mathrm{H}$，$C=200\\,\\mathrm{pF}$，$r=10\\,\\Omega$，$R_L=100\\,\\mathrm{k}\\Omega$，试计算有载品质因数 $Q_L$。[图6：并联谐振电路（见图）]","img":"pro-img/2025_p05.jpg","a":"$Q_L=50$","s":"$\\omega_0=\\dfrac{1}{\\sqrt{LC}}=\\dfrac{1}{\\sqrt{200\\times10^{-6}\\times200\\times10^{-12}}}=5\\times10^6\\ \\mathrm{rad/s}$，特性阻抗 $\\rho=\\omega_0L=1000\\,\\Omega$；电感支路折算并联电阻 $R_p=\\dfrac{L}{Cr}=\\dfrac{200\\times10^{-6}}{200\\times10^{-12}\\times10}=100\\,\\mathrm{k}\\Omega$，与 $R_L$ 并联得 $R_{载}=100k\\parallel100k=50\\,\\mathrm{k}\\Omega$，故 $Q_L=\\dfrac{R_{载}}{\\rho}=\\dfrac{5\\times10^4}{1000}=50$。","t":"真题","y":2025,"src":"西电8112025真题"},{"id":"r25-19","seq":19,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"7. 图7所示电路，已知 $u_s=5\\cos t\\ \\mathrm{V}$，$i_s=6\\cos t\\ \\mathrm{A}$，计算负载 $Z_L$ 为多少时可以获得最大功率。[图7：含 $1\\,\\mathrm{H}$ 电感、$2\\,\\mathrm{F}$ 电容、$1\\,\\Omega$ 电阻的电路（见图）]","img":"pro-img/2025_p05.jpg","a":"$Z_L=Z_{th}^*$（共轭匹配时获得最大功率；$Z_{th}$ 具体数值原文答案页不清）","s":"从 $Z_L$ 两端求戴维南等效阻抗 $Z_{th}$（$\\omega=1$ 时 $1\\,\\mathrm{H}\\to j1\\,\\Omega$，$2\\,\\mathrm{F}\\to -j\\frac12\\,\\Omega$），由最大功率传输定理，当 $Z_L=Z_{th}^*$ 时获得最大功率。（答案页具体数值 OCR 不清）","t":"真题","y":2025,"src":"西电8112025真题"},{"id":"r25-20","seq":20,"part":"电路","qt":"填空","pts":5,"ch":"ec-sinusoidal","q":"8. 电路如图8所示，已知 $U_s=4\\angle0°\\ \\mathrm{V}$，试计算 $i$。[图8：含 $j2\\,\\Omega\\times2$、$2\\,\\Omega$ 与受控源 $2i$ 的电路（见图）]","img":"pro-img/2025_p05.jpg","a":"$i=-2-j2\\,\\mathrm{A}$（即 $2\\sqrt2\\angle-135°\\,\\mathrm{A}$）","s":"设节点电压为 $U$，由节点方程解得 $U=j4\\,\\mathrm{V}$，故 $i=\\dfrac{4\\angle0°-U}{j2}=\\dfrac{4-j4}{j2}=-2-j2\\,\\mathrm{A}$。","t":"真题","y":2025,"src":"西电8112025真题"},{"id":"r25-21","seq":21,"part":"电路","qt":"填空","pts":5,"ch":"ec-twoport","q":"9. 写出如图9所示的二端口网络的 $Z$ 参数。[图9：含 $R_1$、$R_2$、$R_3$ 电阻与受控电流源 $\\beta I_1$ 的二端口网络（见图）]","img":"pro-img/2025_p05.jpg","a":"$\\mathbf{Z}=\\begin{bmatrix}R_1+R_2 & R_2\\\\ R_2-\\beta R_3 & R_2+R_3\\end{bmatrix}$","s":"$U_1=I_1R_1+(I_1+I_2)R_2=(R_1+R_2)I_1+R_2I_2$，$U_2=(I_2-\\beta I_1)R_3+R_2(I_1+I_2)=(R_2-\\beta R_3)I_1+(R_2+R_3)I_2$，故 $Z$ 参数矩阵如上。","t":"真题","y":2025,"src":"西电8112025真题"},{"id":"r25-22","seq":22,"part":"电路","qt":"解答","pts":8,"ch":"ec-analyze","q":"1.（8分）计算图10所示电路中的 $U_{ab}$。[图10：含受控源 $2u$、$1\\,\\mathrm{A}$ 电流源、$2\\,\\Omega$、$0.5\\,\\Omega$ 的电路（见图）]","img":"pro-img/2025_p06.jpg","a":"$U_{ab}=3\\,\\mathrm{V}$","s":"对 $a$ 点列写 KCL，解得 $U=1\\,\\mathrm{V}$，故 $U_{ab}=2+U=3\\,\\mathrm{V}$。（具体 KCL 方程原文 OCR 不清，以答案页结果为准）","t":"真题","y":2025,"src":"西电8112025真题"},{"id":"r25-23","seq":23,"part":"电路","qt":"解答","pts":10,"ch":"ec-dynamic","q":"2.（10分）如图11所示电路，在 $t<0$ 时开关 S 位于\"1\"，电路已经处于稳态，$t=0$ 时开关 S 由\"1\"闭合到\"2\"，求 $t\\ge0$ 时图中电流 $i$ 和电压 $u$ 的零输入响应和零状态响应。[图11：含 $2\\,\\Omega$、$3\\,\\Omega$、$6\\,\\Omega\\times3$、$3\\,\\mathrm{H}$、$6\\,\\mathrm{A}$ 电流源、$12\\,\\mathrm{V}$ 电压源的电路（见图）]","img":"pro-img/2025_p06.jpg","a":"零输入响应：$u_{zi}(t)=-9e^{-2t}\\,\\mathrm{V}$，$i_{zi}(t)=3e^{-2t}\\,\\mathrm{A}$；零状态响应：$i_{zs}(t)=1-e^{-2t}\\,\\mathrm{A}$，$u_{zs}(t)=-9+3e^{-2t}\\,\\mathrm{V}$。","s":"$i(0_-)=3\\,\\mathrm{A}=i(0_+)$。①零输入（将电压源置零）：$R_{eq}=(6\\parallel6)+3=6\\,\\Omega$，$\\tau=\\dfrac{L}{R_{eq}}=\\dfrac{3}{6}=0.5\\ \\mathrm{s}$，故 $i_{zi}(t)=3e^{-2t}\\,\\mathrm{A}$，$u_{zi}(t)=-9e^{-2t}\\,\\mathrm{V}$。②零状态：$i_{zs}(0_+)=0$、$i_{zs}(\\infty)=1\\,\\mathrm{A}$，故 $i_{zs}(t)=1-e^{-2t}\\,\\mathrm{A}$；$u_{zs}(0_+)=-6\\,\\mathrm{V}$、$u_{zs}(\\infty)=-9\\,\\mathrm{V}$，故 $u_{zs}(t)=-9+3e^{-2t}\\,\\mathrm{V}$。（答案页 $u_{zs}$ 初值/稳态 OCR 有歧义，以答案页表达式为准）","t":"真题","y":2025,"src":"西电8112025真题"},{"id":"r25-24","seq":24,"part":"电路","qt":"解答","pts":6,"ch":"ec-sinusoidal","q":"3.（6分）图12所示电路 $\\omega L_1=150\\,\\Omega$，$\\omega L_2=50\\,\\Omega$，$\\omega L_3=100\\,\\Omega$，$\\omega M=20\\,\\Omega$，$\\dfrac{1}{\\omega C}=200\\,\\Omega$，$R=5\\,\\Omega$，$i_s=10+10\\cos\\omega t+10\\cos2\\omega t\\ (\\mathrm{mA})$，求开路电压 $u(t)$。[图12：耦合电感电路（见图）]","img":"pro-img/2025_p06.jpg","a":"$u(t)=6\\cos(\\omega t)\\,\\mathrm{V}$","s":"①直流分量（$10\\,\\mathrm{mA}$）时电感相当于短路，$u(t)=0$；②二次谐波（$2\\omega$）时发生串联谐振，$i_1=0$，$u(t)=0$；③基波（$\\omega$）时 $u=j\\omega M\\,i_1=6\\cos(\\omega t)\\,\\mathrm{V}$。故 $u(t)=6\\cos(\\omega t)\\,\\mathrm{V}$。","t":"真题","y":2025,"src":"西电8112025真题"},{"id":"r25-25","seq":25,"part":"电路","qt":"解答","pts":6,"ch":"ec-analyze","q":"4.（6分）图13为线性电阻电路，当 $i_s=2\\cos10t\\ \\mathrm{A}$、$R_L=2\\,\\Omega$ 时，电流 $i=4\\cos10t+2\\ \\mathrm{A}$；当 $i_s=4\\,\\mathrm{A}$、$R_L=4\\,\\Omega$ 时，电流 $i=8\\,\\mathrm{A}$；计算当 $i_s=5\\,\\mathrm{A}$、$R_L=10\\,\\Omega$ 时，电流 $i$ 为多少 A。[图13：含线性网络 $N$、$R_L$ 与 $2\\,\\Omega$ 电阻的电路（见图）]","img":"pro-img/2025_p07.jpg","a":"$i=6\\,\\mathrm{A}$","s":"设 $N$ 的戴维南等效为 $U_{oc}=ki_s+b$、$R_{eq}$，则 $i=\\dfrac{ki_s+b}{R_{eq}+R_L}$。由 $\\dfrac{2k\\cos10t+b}{R_{eq}+2}=4\\cos10t+2$ 得 $\\dfrac{2k}{R_{eq}+2}=4$、$\\dfrac{b}{R_{eq}+2}=2$；又 $\\dfrac{4k+b}{R_{eq}+4}=8$。解得 $k=16$、$b=16$、$R_{eq}=6\\,\\Omega$。故 $i_s=5\\,\\mathrm{A}$、$R_L=10\\,\\Omega$ 时 $i=\\dfrac{5\\times16+16}{10+6}=\\dfrac{96}{16}=6\\,\\mathrm{A}$。","t":"真题","y":2025,"src":"西电8112025真题"}]};
